INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q001', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the abbreviation PHA stands for:', '["Public Health Act","Private Health Agreement","Provincial Housing Authority","Public Hygiene Administration"]', 0, 'Section 1.1 defines PHA as the Public Health Act (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q002', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the abbreviation CWA stands for:', '["Central Water Authority","Clean Water Act","Crown Water Agreement","Certified Wastewater Act"]', 1, 'Section 1.1 defines CWA as the Clean Water Act (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q003', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the letter K refers to:', '["Soil permeability or hydraulic conductivity","Potassium concentration in effluent","Tank capacity coefficient","Slope gradient factor"]', 0, 'Section 1.1 defines K as soil permeability or hydraulic conductivity (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q004', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the abbreviation lpd means:', '["Litres per day (flow)","Licensed pipe diameter","Load per drainfield","Liquid pressure differential"]', 0, 'Section 1.1 defines lpd as litres per day, a flow measure (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q005', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 inch equals:', '["2.540 cm","2.000 cm","0.254 cm","25.40 cm"]', 0, 'Section 1.2 states 1 in = 2.540 cm (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q006', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 Imperial gallon (IG) equals:', '["5.000 L","4.000 L","3.785 L","4.546 L"]', 3, 'Section 1.2 states 1 IG = 4.546 L (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q007', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 US gallon (USG) equals:', '["4.546 L","3.785 L","3.000 L","2.540 L"]', 1, 'Section 1.2 states 1 USG = 3.785 L (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q008', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 acre equals:', '["4,840 sq ft","40,000 sq ft","10,000 sq ft","43,560 sq ft"]', 3, 'Section 1.2 states 1 acre = 43,560 sq ft (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q009', '1', '1.3 Department of Public Safety (DPS), Technical Inspection Services Head Office', 6, 'What is the mailing address of the DPS Technical Inspection Services Head Office?', '["12 McGloin Street, 2nd Floor, Fredericton, NB E3A 5T8","10 King Street, 1st Floor, Fredericton, NB E3B 1E3","12 McGloin Street, 3rd Floor, Saint John, NB E2L 4S6","21 Regent Street, Fredericton, NB E3B 3W4"]', 0, 'Section 1.3 gives the head office as 12 McGloin Street, 2nd Floor, Fredericton, NB E3A 5T8 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q010', '1', '1.3 Department of Public Safety (DPS), Technical Inspection Services Head Office', 6, 'What is the DPS toll free number listed in the Guidelines?', '["1-844-249-6533","1-800-731-4000","1-888-652-1333","1-844-553-2830"]', 0, 'Section 1.3 lists the DPS toll free number as 1-844-249-6533 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q011', '2', '2 Introduction', 6, 'Under the Public Health Act, an on-site sewage disposal system is defined as:', '["Only a holding tank with an alarm","A septic tank with subsurface disposal field and all other systems not connected to an approved wastewater treatment facility","A pit privy with a vent","Any tank connected to a municipal sewer"]', 1, 'Section 2 defines it as a septic tank with subsurface disposal field plus all other systems not connected to a wastewater treatment facility approved by the Minister under the CWA (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q012', '2', '2 Introduction', 6, 'Who is required to be licensed and hold an approval?', '["Only engineers","Anyone installing, constructing, repairing, or replacing a system or any of its parts","Only commercial installers","Only the property owner"]', 1, 'Section 2 states it is mandatory that anyone installing, constructing, repairing, or replacing a system or any of its parts be licensed and have an approval (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q013', '2', '2 Introduction', 6, 'Approvals are issued for wastewater from personal hygiene, sanitation, cooking and laundering. Which of the following is NOT covered?', '["Kitchen wastewater","Liquid wastes from industrial processes","Laundry wastewater","Greywater"]', 1, 'Section 2 includes greywater but excludes liquid and water-carried wastes from industrial or manufacturing processes, sump pumps, gutters, drainage pipes and runoff water (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q014', '2', '2.1 Engineered Systems', 7, 'An engineered system is mandatory when the estimated daily sewage flow exceeds:', '["5,000 L/d","4,546 L/d","6,000 L/d","5,460 L/d"]', 3, 'Section 2.1 requires engineered systems when estimated daily sewage flows exceed 5,460 L/d (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q015', '2', '2.1 Engineered Systems', 7, 'An engineered on-site sewage disposal system must be:', '["Designed by DPS staff and installed by anyone","Installed by a Licensee and designed by a Professional Engineer licensed through APEGNB","Designed by the Licensee and installed by the homeowner","Installed by a plumber with no design needed"]', 1, 'Section 2.1 requires installation by a Licensee and design by a Professional Engineer licensed through the Association of Professional Engineers and Geoscientists of New Brunswick (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q016', '2', '2.1 Engineered Systems', 7, 'Which of these is a condition that makes an engineered system mandatory?', '["The system uses a plastic chamber","The lot is larger than one acre","The owner prefers it","Suitable imported sand is not available"]', 3, 'Section 2.1 lists conditions including flows over 5,460 L/d, unsuitable soils, unavailable suitable imported sand, and effluent stronger than typical domestic wastewater (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q017', '3', '3.1 Soil Conditions', 7, 'What is the purpose of the soil in an on-site sewage disposal system?', '["To provide infiltration, dispersal, and final treatment of effluent before it reaches bedrock, groundwater or setbacks","To prevent freezing of the pipes","To support the weight of the tank","To filter out grease only"]', 0, 'Section 3.1 states the soil provides infiltration, dispersal, and final treatment of effluent before it reaches bedrock, groundwater or horizontal setbacks (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q018', '3', '3.1 Soil Conditions', 7, 'Test holes must be located within what distance of the proposed disposal field?', '["30 m (100 ft)","10 m (33 ft)","1 m (3 ft)","3 m (10 ft)"]', 3, 'Section 3.1 requires test holes within approximately 3 m (10 feet) of the proposed disposal field (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q019', '3', '3.1 Soil Conditions', 7, 'How deep must a test hole be?', '["At least 1.8 m (6 ft) unless bedrock is encountered","At least 2.5 m (8 ft)","At least 1.0 m (3.3 ft)","Exactly 1.2 m (4 ft)"]', 0, 'Section 3.1 requires the test hole to be at least 1.8 m (6 feet) deep unless bedrock is encountered (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q020', '3', '3.1 Soil Conditions', 7, 'Why should a test hole NOT be dug directly in the existing field area?', '["It makes the soil too compact","It could contaminate groundwater","It is too expensive","It voids the warranty"]', 1, 'Section 3.1 warns that digging a test hole directly in the existing field area could contaminate groundwater (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q021', '3', '3.1 Soil Conditions', 8, 'An in-ground trench is permitted to be installed in which soil categories?', '["A only","A, B or C","A and B only","D only"]', 1, 'Section 3.1 states an in-ground trench is permitted in A, B or C soil (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q022', '3', '3.1 Soil Conditions', 8, 'Category D soil means the soil is too permeable or impermeable. What is required in that case?', '["A raised mound field or engineered design","A smaller septic tank","No system at all","A standard in-ground trench"]', 0, 'Section 3.1 states Category D cannot be used to select a system, so a raised mound field or engineered design is required (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q023', '3', '3.1 Soil Conditions', 8, 'What is the Kfs range for Type A soil?', '["1x10-4 to 6x10-4 m/sec","2x10-5 to 1x10-4 m/sec","3x10-6 to 2x10-5 m/sec","Less than 3x10-6 m/sec"]', 0, 'Section 3.1 gives Type A as 1x10-4 m/sec to 6x10-4 m/sec (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q024', '3', '3.1 Soil Conditions', 8, 'What is the Kfs range for Type C soil?', '["2x10-5 to 1x10-4 m/sec","3x10-6 to 2x10-5 m/sec","1x10-4 to 6x10-4 m/sec","Greater than 6x10-4 m/sec"]', 1, 'Section 3.1 gives Type C as 3x10-6 m/sec to 2x10-5 m/sec (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q025', '3', '3.1 Soil Conditions', 42, 'A moist soil sample forms a weak ball that only stays together if handled carefully, with flakes or very short ribbons 1.5 to 2.5 cm long, and feels grainy and not sticky. This indicates:', '["Category B (Moderate) fine sand","Category C (Fair) sandy loam","Category D clay","Category A (Good) coarse sand"]', 1, 'Table 6 describes Category C (Fair) sandy loam this way: weak ball, flakes or very short ribbons 1.5 to 2.5 cm, grainy and not sticky (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q026', '3', '3.2 Slope and Interceptor Drains', 9, 'What is the purpose of an interceptor drain or diversion ditch?', '["To carry effluent to the field","To connect the tank to the house","To vent the septic tank","To divert or intercept surface water and groundwater upslope of a disposal field"]', 3, 'Section 3.2 states an interceptor drain or diversion ditch diverts or intercepts surface water and groundwater upslope of a disposal field to prevent saturation during wet seasons (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q027', '3', '3.2 Slope and Interceptor Drains', 9, 'Where is an interceptor drain placed relative to the disposal field?', '["Upslope of the disposal field","Downslope of the field","Inside the septic tank","Directly under the field"]', 0, 'Section 3.2 places the interceptor drain upslope of the disposal field to stop water moving down the slope from saturating the field (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q028', '3', '3.3 Separation Distances', 10, 'What is the required separation distance from a drilled well to the disposal field?', '["90 m (300 ft)","15 m (50 ft)","23 m (75 ft)","30 m (100 ft)"]', 2, 'Table 1 in Section 3.3 requires 23 m (75 ft) from a drilled well to the disposal field (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q029', '3', '3.3 Separation Distances', 10, 'What is the required separation distance from a drilled well to the septic tank?', '["23 m (75 ft)","15 m (50 ft)","30 m (100 ft)","10 m (33 ft)"]', 1, 'Table 1 in Section 3.3 requires 15 m (50 ft) from a drilled well to the septic tank (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q030', '3', '3.3 Separation Distances', 10, 'What separation distance applies to a dug well or sandpoint well from both the septic tank and the disposal field?', '["45 m (150 ft)","23 m (75 ft)","30 m (100 ft)","15 m (50 ft)"]', 2, 'Table 1 in Section 3.3 requires 30 m (100 ft) from a dug well or sandpoint well to both the tank and the field (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q031', '3', '3.3 Separation Distances', 10, 'What is the required separation from a body of water (normal high water mark, not used as a potable supply) to the disposal field?', '["75 m (250 ft)","30 m (100 ft)","15 m (50 ft)","3 m (10 ft)"]', 2, 'Table 1 in Section 3.3 requires 15 m (50 ft); note that work within 30 m (100 ft) of a watercourse needs a Watercourse Alteration Permit (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q032', '3', '3.3 Separation Distances', 10, 'For a body of water used as a designated potable water supply, what is the required distance from the septic tank?', '["90 m (300 ft)","30 m (100 ft)","15 m (50 ft)","75 m (250 ft)"]', 0, 'Table 1 in Section 3.3 requires 90 m (300 ft) from the septic tank to a body of water used as a designated potable water supply (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q033', '3', '3.3 Separation Distances', 10, 'What is the required separation distance from a building foundation to the disposal field?', '["5.0 m (16 ft)","1.5 m (5 ft)","15 m (50 ft)","3.0 m (10 ft)"]', 3, 'Table 1 in Section 3.3 requires 3.0 m (10 ft) from a building foundation to the disposal field (1.5 m to the tank) (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q034', '3', '3.3 Separation Distances', 10, 'What is the required separation distance from a property line or intermittent ditch to the disposal field?', '["1.5 m (5 ft)","3.0 m (10 ft)","10 m (33 ft)","15 m (50 ft)"]', 1, 'Table 1 in Section 3.3 requires 3.0 m (10 ft) from a property line or intermittent ditch (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q035', '3', '3.3 Separation Distances', 10, 'What is the required vertical separation from the invert (bottom) of the distribution pipe to limiting factors such as bedrock or groundwater?', '["1.8 m (6 ft)","1.0 m (3.3 ft)","1.2 m (4 ft)","0.6 m (2 ft)"]', 2, 'Table 1 in Section 3.3 requires 1.2 m (4 ft) vertically from the pipe invert to limiting factors (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q036', '3', '3.3.1 Watercourses & Wetlands', 11, 'If work is to be done within 30 m (100 ft) of a wetland or watercourse, whose responsibility is it to contact the Department of Environment and Local Government and obtain permits?', '["The property owner''s","No one, permits are automatic","The installer''s","The municipality''s"]', 0, 'Section 3.3.1 states it is the property owner''s responsibility to ensure DELG is contacted and all necessary permits obtained (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q037', '3', '3.3.1 Watercourses & Wetlands', 11, 'Under the Clean Water Act, a wetland is land that has a water table at, near or above the surface and:', '["Sustains aquatic processes as shown by hydric soils, hydrophytic vegetation and wet-adapted biology","Is used for farming","Is covered by forest","Has a drilled well"]', 0, 'Section 3.3.1 defines a wetland as land with a water table at, near or above the surface that sustains aquatic processes indicated by hydric soils, hydrophytic vegetation and adapted biological activity (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q038', '3', '3.3.2 Wells', 11, 'An abandoned well exists within the setback distances of a proposed system. What must happen before an Approval is issued?', '["Nothing, abandoned wells are ignored","The system must be moved 100 m away","The well must be properly decommissioned or proof of decommissioning provided","The owner must fill it with sand only"]', 2, 'Section 3.3.2 requires the well to be properly decommissioned or sufficient proof provided, with proof submitted along with the Notice of Installation (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q039', '3', '3.3.3 Exemptions', 12, 'For a vacant lot smaller than 4000 m2 (1 acre) approved by the Planning Commission prior to 1976, the Department may grant an exemption up to what maximum flow?', '["1705 L/day","1365 L/day EDSF","750 L/day","1022 L/day"]', 1, 'Section 3.3.3 allows an exemption up to a maximum of 1365 L/day EDSF for such lots, provided all separation distances are met (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q040', '3', '3.4 Lot Layout', 13, 'Where should the well be located relative to the on-site sewage disposal system where possible?', '["Upslope of the system","Under the disposal field","Beside the septic tank","Downslope of the system"]', 0, 'Section 3.4 states the well should be located upslope of the on-site sewage disposal system where possible (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q041', '3', '3.4 Lot Layout', 13, 'When assessing a lot, separation distances must be checked to bodies of water within what distance of any part of the proposed system?', '["200 m (660 ft)","30 m (100 ft)","50 m (165 ft)","100 m (330 ft)"]', 3, 'Section 3.4 lists separation distances to bodies of water within 100 m (330 ft) of any part of the proposed system (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q042', '4', '4.1 Estimated Daily Sewage Flow', 14, 'Estimated daily sewage flows must be calculated based on:', '["The size of the lot only","The number of bathrooms divided by two","The design flow criteria in Appendix D","The installer''s experience"]', 2, 'Section 4.1 requires flows to be calculated based on the design flow criteria in Appendix D (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q043', '4', '4.2 System Sizing', 14, 'The disposal field must be sized based on the soil with the slowest permeability within what depth below the distribution pipe?', '["1.8 m (6 ft)","1.2 m (4 ft)","0.6 m (2 ft)","3.0 m (10 ft)"]', 1, 'Section 4.2 requires sizing based on the slowest permeability within 1.2 m (4 feet) below the distribution pipe (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q044', '4', '4.2 System Sizing', 14, 'How does disposal field size change with flow and soil permeability?', '["It stays the same regardless","It decreases as flow increases","It increases as flow increases and permeability decreases","It depends only on lot size"]', 2, 'Section 4.2 states the disposal field size increases as the flow increases and soil permeability decreases (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q045', '4', '4.3 Septic Tank', 14, 'What is the minimum liquid capacity of a prefabricated septic tank?', '["2000 L","5460 L","3410 L","4090 L"]', 2, 'Section 4.3 requires a minimum liquid capacity of 3410 L (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q046', '4', '4.3 Septic Tank', 14, 'A septic tank must have two compartments. What share of the total capacity must the first compartment hold?', '["One-third","Two-thirds","Three-quarters","One-half"]', 1, 'Section 4.3 requires two compartments with the first equal to two-thirds of total septic tank capacity (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q047', '4', '4.3 Septic Tank', 15, 'Why must a septic tank have baffles at the inlet and outlet ends?', '["To support the lid","To anchor the tank","To measure sludge depth","To prevent short-circuiting or direct flow-through of effluent"]', 3, 'Section 4.3 requires baffles at inlet and outlet to prevent short-circuiting or direct flow through of effluent (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q048', '4', '4.3 Septic Tank', 15, 'Which tank material is NOT permitted?', '["Fibreglass","Steel","Polyethylene","Concrete"]', 1, 'Section 4.3 permits concrete, fibreglass or polyethylene; steel tanks are not permitted due to higher corrosion rates (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q049', '4', '4.3 Septic Tank', 14, 'Prefabricated septic tanks must conform to which standard and show what?', '["CSA Standard B66 with a visible stamp","NSF Standard 46 with a date code","No standard applies","CSA Standard B65 with a serial plate"]', 0, 'Section 4.3 requires prefabricated tanks to conform to the most recent CSA Standard B66 and have a visible stamp (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q050', '4', '4.3 Septic Tank', 15, 'The septic tank effluent filter must meet which standard?', '["NSF Standard 40","CSA Standard B65","NSF Standard 46","CSA Standard B66"]', 2, 'Section 4.3 requires an effluent filter meeting NSF Standard 46, easily accessible for maintenance (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q051', '4', '4.3 Septic Tank', 15, 'What is the minimum slope of the pipe from the house to the septic tank?', '["Level with no slope","3 mm per 300 mm of length or 1%","1 mm per 300 mm","10 mm per 300 mm"]', 1, 'Section 4.3 requires a minimum slope of 3 mm per 300 mm of length or 1% (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q052', '4', '4.3 Septic Tank', 15, 'What is the minimum liquid depth in a septic tank?', '["0.9 m (3 ft)","1.2 m (4 ft)","0.6 m (2 ft)","1.8 m (6 ft)"]', 0, 'Section 4.3 states the minimum liquid depth in a tank is 0.9 m (3 ft) (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q053', '4', '4.4 Conventional Design', 17, 'Under Regulation 2009-137, a conventional system is a septic tank with subsurface disposal field with flows not exceeding:', '["5460 lpd","8180 lpd","1365 lpd","3410 lpd"]', 0, 'Section 4.4 defines a conventional system as having sewage flows not exceeding 5460 lpd (p.17).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q054', '4', '4.4 Conventional Design', 17, 'How must distribution lines be laid in a disposal field?', '["Parallel to the contour and perpendicular to groundwater flow","Vertically into the soil","In a circular pattern","Down the slope of the land"]', 0, 'Section 4.4 requires distribution lines laid parallel to the contour (across the natural slope) and perpendicular to groundwater flow (p.17).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q055', '4', '4.4 Conventional Design', 17, 'A distribution box must be installed level and must have:', '["A baffle in front of the inlet","Only one outlet","A steel casing","No inlet at all"]', 0, 'Section 4.4 requires a distribution box to be installed level with a baffle in front of the inlet (p.17).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q056', '4', '4.4 Conventional Design', 17, 'What size of crushed rock should geotextile be placed over before backfilling?', '["10 mm to 50 mm","100 mm to 150 mm","50 mm to 100 mm","5 mm to 10 mm"]', 0, 'Section 4.4 recommends geotextile over crushed rock (10 mm to 50 mm) before backfilling (p.17).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q057', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What is the minimum trench width for a pipe and stone system?', '["600 mm (24 in)","450 mm (18 in)","300 mm (12 in)","900 mm (36 in)"]', 1, 'Table 2 in Section 4.4.1 gives a minimum trench width of 450 mm (18 in) (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q058', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What is the maximum trench length for a pipe and stone system?', '["15 m (50 ft)","60 m (200 ft)","30 m (100 ft)","10 m (33 ft)"]', 0, 'Table 2 in Section 4.4.1 gives a maximum trench length of 15 m (50 ft) (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q059', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What depth of clean crushed stone is required under and over the distribution pipe?', '["300 mm / 100 mm","100 mm / 25 mm","50 mm / 50 mm","200 mm / 50 mm"]', 3, 'Table 2 in Section 4.4.1 requires 200 mm under and 50 mm over the pipe (8 in / 2 in) (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q060', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What is the required slope of the perforated distribution pipe?', '["25 mm per 15 m","50 mm per 15 m (2 in per 50 ft)","Level with no slope","100 mm per 15 m"]', 1, 'Table 2 in Section 4.4.1 requires a slope of 50 mm per 15 m (2 in per 50 ft) (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q061', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What is the minimum total field length for a pipe and stone disposal field?', '["60 m (200 ft)","90 m (300 ft)","30 m (100 ft)","45 m (150 ft)"]', 0, 'Table 2 in Section 4.4.1 requires a minimum total field length of 60 m (200 ft) (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q062', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What are the soil cover requirements for a disposal field?', '["Minimum 10 cm cover with no topsoil needed","Minimum 30 cm cover with at least 10 cm of topsoil; cover not to exceed 60 cm","Exactly 45 cm of clay","No cover required"]', 1, 'Section 4.4.1 requires a minimum 30 cm (12 in) of air-permeable soil cover with at least 10 cm (4 in) of topsoil, not exceeding 60 cm (24 in) unless alternative aeration is provided (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q063', '4', '4.4.2 Raised Mound Trench System', 21, 'A raised mound system is needed when a test pit identifies:', '["A lot larger than one acre","Limiting factors such as bedrock, groundwater, impermeable soil, or soil that is too permeable","A nearby drilled well","Perfectly draining sand"]', 1, 'Section 4.4.2 lists limiting factors: bedrock, groundwater or seasonal high water table, impermeable soil like clay, or soil that is too permeable (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q064', '4', '4.4.2 Raised Mound Trench System', 21, 'How must the area under a proposed mound be prepared?', '["Compacted with a roller","Left completely untouched","Scarified parallel to the slope, with no equipment driven over the scarified area","Covered with plastic sheeting"]', 2, 'Section 4.4.2 requires scarification parallel to the slope using a cultivator, mould board or chisel plough, with no equipment driven over the scarified area (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q065', '4', '4.4.2 Raised Mound Trench System', 21, 'Imported sand for a mound must be placed in lifts not exceeding:', '["150 mm","300 mm","600 mm","900 mm"]', 1, 'Section 4.4.2 requires sand placed in lifts not exceeding 300 mm so it does not settle after placement (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q066', '4', '4.4.2 Raised Mound Trench System', 21, 'Before imported sand is placed for a mound, what must be done to the site?', '["A concrete pad poured","Nothing at all","The area flooded with water","Stumps removed and sod and root layers stripped"]', 3, 'Section 4.4.2 requires stumps to be removed and sod and root layers stripped before imported sand is placed (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q067', '4', '4.4.2.1 Imported Sand', 22, 'For imported sand, the material passing the 75 micrometre (No. 200) sieve must be:', '["More than 50% passing","Exactly 15% passing","8% or less passing, with less than 5% recommended","At least 20% passing"]', 2, 'Table 3 requires 8% or less passing the No. 200 sieve in the sand fraction, with less than 5% recommended (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q068', '4', '4.4.2.1 Imported Sand', 22, 'What are the Table 3 specifications for D10 and Cu of imported sand?', '["D10 0.05 to 0.10 mm; Cu 6 to 12","D10 0.15 to 0.50 mm; Cu 1 to 6.0","D10 0.01 to 0.05 mm; Cu 10 to 20","D10 1.0 to 2.0 mm; Cu 0.5 to 1"]', 1, 'Table 3 specifies D10 of 0.15 to 0.50 mm and Cu (D60/D10) of 1 to 6.0 in the sand fraction (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q069', '4', '4.4.2.1 Imported Sand', 22, 'What is the required KFS (permeability) range for imported sand?', '["Less than 1x10-6 m/s","5x10-5 to 6x10-4 m/s","1x10-4 to 6x10-4 m/s","3x10-6 to 2x10-5 m/s"]', 1, 'Table 3 specifies KFS of 5x10-5 to 6x10-4 m/s for imported sand (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q070', '4', '4.4.2.1 Imported Sand', 23, 'When permeability is determined by laboratory hydraulic conductivity testing (Ks), what is the relationship to KFS?', '["KFS is typically Ks divided by 2","There is no relationship","KFS equals Ks","KFS is typically Ks times 10"]', 0, 'Section 4.4.2.1 notes that laboratory testing determines Ks, and KFS is typically Ks/2 (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q071', '4', '4.4.2.2 Apron and Taper', 23, 'In a mound disposal field, how wide must the apron be?', '["6 m (20 ft) on all downslope ends and 3 m (10 ft) on all other sides","1.5 m on all sides","10 m on all sides","3 m on all sides"]', 0, 'Section 4.4.2.2 requires the apron to be 6 m (20 feet) on all downslope ends and 3 m (10 feet) on all other sides (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q072', '4', '4.4.2.2 Apron and Taper', 23, 'What slope ratio is required for the taper of a mound disposal field?', '["4:1 horizontal to vertical","10:1 horizontal to vertical","2:1 horizontal to vertical","1:1 horizontal to vertical"]', 0, 'Section 4.4.2.2 requires the taper at a 4:1 (horizontal:vertical) ratio from the edge of the apron to original ground elevation (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q073', '4', '4.4.2.2 Apron and Taper', 24, 'What is the required finished elevation of backfill above the top of the pipe in a mound?', '["0.3 m to 0.6 m (1 ft to 2 ft)","No backfill required","0.1 m to 0.2 m","1.0 m to 1.5 m"]', 0, 'Section 4.4.2.2 defines finished elevation as 0.3 m (1 ft) to 0.6 m (2 ft) of backfill above the top of the pipe, with at least 100 mm of topsoil finished with sod or seed (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q074', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What size of concrete leaching chamber is approved for use in New Brunswick?', '["2.0 m x 2.0 m x 1.0 m deep","1.2 m x 2.4 m x 0.6 m deep","0.6 m x 1.2 m x 0.6 m deep","1.0 m x 2.0 m x 0.5 m deep"]', 1, 'Section 4.4.3 states the approved size is 1.2 m x 2.4 m x 0.6 m deep (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q075', '4', '4.4.3 Leaching Chamber (Concrete)', 24, 'How much coarse gravel is required around the outside of concrete leaching chambers, and what size is it?', '["No gravel required","15 cm of 10 to 50 mm gravel","Minimum 30 cm (12 in) of 19 mm to 76 mm (3/4 in to 3 in) gravel","60 cm of sand"]', 2, 'Section 4.4.3 requires a minimum of 30 cm (12 in) of coarse gravel, classified as 19 mm to 76 mm (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q076', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'Where more than one row of leaching chambers is required, what is the minimum centre-to-centre spacing?', '["1.5 m (5 ft)","15 m (50 ft)","3 m (10 ft)","6 m (20 ft)"]', 3, 'Section 4.4.3 requires rows to be placed at a minimum of 6 m (20 ft) centre to centre (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q077', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'For concrete leaching chambers, the distance to limiting factors is measured from where, and what is the minimum?', '["From the top of the unit, 0.6 m","From the pipe invert, 1.2 m","From the bottom of the unit, at least 1 m (3.3 ft)","From the trench edge, 3 m"]', 2, 'Section 4.4.3 requires the distance measured from the bottom of the unit (not the pipe invert), at least 1 m (3.3 ft) from limiting factors (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q078', '4', '4.4.4 Infiltrative Chamber (Plastic)', 26, 'What is the maximum length of any one plastic infiltrative chamber distribution line?', '["15 m (50 ft)","30 m (100 ft)","60 m (200 ft)","10 m (33 ft)"]', 0, 'Section 4.4.4 states no one line shall exceed 15 m (50 ft) (p.26).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q079', '4', '4.4.4 Infiltrative Chamber (Plastic)', 27, 'For plastic infiltrative chambers, what is the minimum distance from the bottom of the trench (or unit) to a limiting factor?', '["1.2 m (4 ft)","0.6 m (2 ft)","1.8 m (6 ft)","1.0 m (3.3 ft)"]', 3, 'Section 4.4.4 requires at least 1.0 m (3.3 ft) measured from the bottom of the trench or unit (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q080', '4', '4.4.4 Infiltrative Chamber (Plastic)', 26, 'What sand must be used with plastic infiltrative chambers?', '["Sand meeting the manufacturer''s specifications","Any pit-run sand","Clay-rich sand","Beach sand"]', 0, 'Section 4.4.4 requires sand meeting the manufacturer''s specifications, with a soil analysis recommended if uncertain (p.26).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q081', '4', '4.4.4.1 Approved For Use in New Brunswick', 27, 'Which of the following infiltrative chambers is approved for use in New Brunswick?', '["SepticDome Pro (8 ft)","EcoChamber XL (10 ft)","DrainMaster 2000 (3 ft)","Quick4 Standard (4 ft) by Infiltrator Water Technologies"]', 3, 'Section 4.4.4.1 lists Infiltrator Water Technologies products including Quick4 Standard (4 ft) as approved (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q082', '4', '4.4.4.1 Approved For Use in New Brunswick', 28, 'Approved infiltrative chambers receive what reduction in total length compared to a perforated pipe and stone system?', '["No reduction","50% reduction","25% reduction","75% reduction"]', 1, 'Section 4.4.4.1 states each listed chamber receives a 50% reduction in total length required for a perforated pipe and stone system (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q083', '4', '4.4.5 Holding Tank', 28, 'What is the minimum size of a holding tank?', '["3410 L (750 IG)","9000 L (2000 IG)","5460 L (1200 IG)","12000 L (2640 IG)"]', 1, 'Section 4.4.5 requires holding tanks to be sized for the estimated daily volume with a minimum of 9000 L (2000 IG) (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q084', '4', '4.4.5 Holding Tank', 29, 'A holding tank must have a signalling device that activates when the tank is 80% full. If used with a pump, what additional interlock is required?', '["A warning device inter-wired with the pump to prevent pump operation when the tank is 90% full","Nothing additional","The alarm must be disconnected","The pump must run faster"]', 0, 'Section 4.4.5 requires the alarm at 80% full, and with a pump the warning device must be inter-wired to prevent pump operation at 90% full (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q085', '4', '4.4.5 Holding Tank', 28, 'Holding tanks are considered for temporary use such as special events or construction camps not exceeding:', '["6 months","24 months","12 months","36 months"]', 2, 'Section 4.4.5 allows temporary use for special events or construction/work camps not exceeding 12 months; seasonal cottage use is not considered temporary (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q086', '4', '4.4.5 Holding Tank', 28, 'Holding tanks must conform to which standard?', '["CSA Standard B65","NSF Standard 46","CSA Standard B181.1","CSA Standard B-66 or certification of equivalency"]', 3, 'Section 4.4.5 requires conformity to the most recent CSA Standard B-66 or certification of equivalency acceptable to the Minister (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q087', '4', '4.4.5 Holding Tank', 28, 'What separation distances apply to a holding tank?', '["The same as those for septic tanks in Table 1","Double those for septic tanks","Half those for septic tanks","No separations apply"]', 0, 'Section 4.4.5 states separation distances are the same as those for septic tanks in Table 1 (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q088', '4', '4.4.6 Pit Privy', 29, 'What separation distances apply to a pit privy?', '["Half the septic tank distances","Only well separations apply","The same as for septic tanks in Table 1","No separations required"]', 2, 'Section 4.4.6 states the same separation distances apply as indicated for septic tanks in Table 1 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q089', '4', '4.4.6 Pit Privy', 29, 'An earthen pit or vault privy will only be considered when:', '["It is for commercial use","The soil is Category A","The lot has no greywater being discharged (no well, no electricity)","The lot is larger than one acre"]', 2, 'Section 4.4.6 allows an earthen pit or vault privy only when the lot has no greywater discharge, i.e. no well and no electricity (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q090', '4', '4.4.6 Pit Privy', 29, 'Child protection bars on a privy holding tank must be spaced so that:', '["An adult hand cannot pass","A 50 mm sphere cannot pass","They are 200 mm apart","A spherical object with a diameter of 100 mm (4 in) cannot pass"]', 3, 'Section 4.4.6 requires bars spaced so a 100 mm (4 in) diameter sphere cannot pass, where public access is expected (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q091', '4', '4.4.6 Pit Privy', 30, 'What are the depth limits for an earthen pit privy?', '["Exactly 1.8 m deep","Depth does not matter","No more than 3 m deep with no separation needed","No more than 1.2 m (4 ft) below original grade, with minimum 1.2 m (4 ft) separation to limiting factors"]', 3, 'Section 4.4.6 requires minimum 1.2 m (4 ft) separation to limiting factors and a pit depth not greater than 1.2 m (4 ft) below original grade (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q092', '4', '4.4.7 Pump', 31, 'A pump or siphon is required when the total linear length of the disposal field exceeds:', '["300 m (1000 ft) for any system","15 m (50 ft) for any system","150 m (500 ft) for pipe and stone, or 75 m (246 ft) for plastic infiltrators","60 m (200 ft) for any system"]', 2, 'Section 4.4.7 requires a pump/siphon when the field exceeds 150 m (500 ft) of pipe and stone or 75 m (246 ft) of plastic infiltrators (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q093', '4', '4.4.7 Pump', 32, 'If a pump is needed only because of elevation, the field is not considered pressure-dosed. If needed because of field size, the field must be pressure-dosed and the pump must dose at:', '["50 to 75% of total capacity","25 to 50% of total capacity","10 to 25% of total capacity","100% of total capacity"]', 0, 'Section 4.4.7 requires pressure-dosed fields to be dosed at 50 to 75% of total capacity at any one time (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q094', '4', '4.4.7 Pump', 32, 'Before covering a pump chamber assembly, the Licensee must:', '["Notify the neighbours","Contact DPS for inspection of the electrical components","Fill the chamber with water","Disconnect the alarm"]', 1, 'Section 4.4.7 requires the Licensee to contact DPS for inspection of electrical components prior to covering the pump chamber assembly (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q095', '4', '4.4.7 Pump', 32, 'Which statement about pump chamber wiring is correct?', '["Extension cords are acceptable","Wiring does not need to meet electrical codes","A receptacle may be installed inside the sump","There shall be no receptacle or junction box inside the sump, and all feeders shall be installed by a licensed electrical contractor"]', 3, 'Section 4.4.7 prohibits receptacles or junction boxes inside the sump and requires feeders installed by a licensed electrical contractor (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q096', '4', '4.4.7 Pump', 32, 'A plastic infiltrative chamber disposal field where pressure-dosing is required is:', '["Not a conventional design and cannot be designed by a Licensee","Still a conventional design","Only for commercial use","Exempt from all approvals"]', 0, 'Section 4.4.7 states such a field is not a conventional design and cannot be designed by a Licensee; it is a non-conventional design (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q097', '4', '4.4.8 Grease Trap or Chamber', 34, 'Grease chambers are typically required for:', '["All residential homes","Holding tanks only","Some commercial and institutional uses such as restaurants or school cafeterias","Only pit privies"]', 2, 'Section 4.4.8 states grease chambers are not usually required on residential lines but are required in some commercial and institutional applications such as restaurants or school cafeterias (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q098', '4', '4.4.8 Grease Trap or Chamber', 35, 'Why must chemical compounds that dissolve grease NOT be added to grease traps?', '["They are illegal everywhere","They are too expensive","They clean out the trap, letting dissolved grease re-solidify in the disposal field, which may cause system failure","They make the trap too cold"]', 2, 'Section 4.4.8 prohibits grease-dissolving chemicals because they let dissolved grease re-solidify in the disposal field and may cause the system to fail (p.35).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q099', '4', '4.4.9 Oil / Water Separator', 35, 'Effluent from an oil/water separator:', '["Is not permitted to be discharged to a domestic on-site sewage disposal system","May go to any domestic system","Can go to a pit privy","Needs no approval"]', 0, 'Section 4.4.9 prohibits discharge of oil/water separator effluent to a domestic on-site sewage disposal system (p.35).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q100', '4', '4.4.9 Oil / Water Separator', 36, 'Small amounts of chemicals such as paints, solvents or thinners in separator effluent are a concern because they:', '["Make the effluent too cold","Increase the water table","Can kill the bacteria that break down organic matter in the system","Stain the pipes"]', 2, 'Section 4.4.9 notes such chemicals can kill the bacteria that break down organic matter in an on-site sewage disposal system (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q101', '4', '4.5 Repairs', 36, 'Under Section 24 of the Public Health Act, which of the following requires an approval?', '["Mowing grass over the field","Relocating a septic tank horizontally or vertically","Painting the privy door","Replacing a toilet indoors"]', 1, 'Section 4.5 states an approval is required to install, construct, repair or replace a system, including relocating a septic or holding tank (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q102', '4', '4.5 Repairs', 36, 'Which activity is listed as a repair requiring an application for approval?', '["Anytime an excavation is required within the limits of the disposal field, including the apron or taper","Raking leaves off the mound","Reading the water meter","Testing the alarm battery"]', 0, 'Section 4.5 lists excavation within the disposal field limits, including apron or taper, as a repair requiring approval (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q103', '4', '4.5 Repairs', 36, 'If an investigation is needed to determine the scope of repairs, what must happen first?', '["Wait one year","Obtain an Approval first, with the application describing the planned investigative actions","Notify the neighbours","Start digging immediately"]', 1, 'Section 4.5 requires an Approval first when investigation is needed, with the application describing the investigative actions (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q104', '4', '4.6 Non-Conventional Design', 36, 'Under Regulation 09-137, a conventional system has sewage flows not exceeding 5460 litres per day. A non-conventional system is defined as:', '["Any system with a septic tank","Only a pit privy","An on-site sewage disposal system other than a conventional system","Only a holding tank"]', 2, 'Section 4.6 defines a non-conventional system as an on-site sewage disposal system other than a conventional system (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q105', '4', '4.6 Non-Conventional Design', 36, 'Which of the following is an example of a non-conventional system?', '["Pipe and stone trench","Contour system","Standard pit privy","Concrete leaching chamber field"]', 1, 'Section 4.6 lists contour systems, sloping sand filters, package plants, pressure-dosed infiltrative chambers, peat filters, constructed wetlands and large diameter matted pipe as examples (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q106', '4', '4.6 Non-Conventional Design', 37, 'Installers licensed to install contour systems must follow which document?', '["The Selection and Installation Manual for Contour Sewage Disposal Systems in New Brunswick","No manual is required","The CSA B65 standard only","The National Plumbing Code"]', 0, 'Section 4.6 requires contour installers to follow the most recent Selection and Installation Manual for Contour Sewage Disposal Systems in New Brunswick (p.37).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q107', '4', '4.6 Non-Conventional Design', 37, 'How does someone apply for a non-conventional installer licence?', '["Automatically with a conventional licence","In writing to the Department of Public Safety with appropriate proof of training","By phone call only","Through the municipality"]', 1, 'Section 4.6 states a non-conventional licence can be applied for in writing to the Department of Public Safety with appropriate proof of training (p.37).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q108', '5', '5.2 Licensing Requirements', 39, 'What is the licensing fee for a conventional installer licence?', '["$900","$400","$150","$350"]', 1, 'Section 5.2 sets the conventional licensing fee at $400 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q109', '5', '5.2 Licensing Requirements', 39, 'What is the licensing fee for a non-conventional installer licence?', '["$150","$350","$400","$300"]', 1, 'Section 5.2 sets the non-conventional licensing fee at $350 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q110', '5', '5.2.1 Issuance', 40, 'Installer licences are issued to:', '["The property owner","Individual installers by name","The municipality","A company or business"]', 3, 'Section 5.2.1 states licences are issued to a company/business, not to named individuals (p.40).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q111', '5', '5.1 Licensing', 39, 'A conventional installer licence allows installation of mound, trench or area bed systems with pipe and stone, leaching chambers or infiltrative chambers, and includes holding tanks and pit privies, but excludes:', '["Pump chambers","Concrete chambers","Septic tanks","A contour system or an infiltrative chamber pressure-dosed system"]', 3, 'Section 5.1 excludes a contour system and an infiltrative chamber pressure-dosed system from the conventional licence (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q112', '5', '5.2.1 Issuance', 40, 'When do installer licences expire each year?', '["June 30","September 30","December 31","March 31"]', 3, 'Section 5.2.1 states licences expire on March 31st of each year (p.40).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q113', '5', '5.2.1 Issuance', 40, 'A licensed company must at all times employ at least one person who completed the course and passed the exam. If that person leaves, how long does the company have to appoint a replacement before the licence is revoked?', '["30 days","7 days","90 days","12 months"]', 0, 'Section 5.2.1 allows 30 days from the employee''s termination date to appoint a replacement, otherwise the licence is revoked (p.40).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q114', '5', '5.3 Course and Exam', 41, 'In which month is the Provincial Installer Course offered each year?', '["October","July","January","April"]', 3, 'Section 5.3 states the course is offered by Health Protection Services in April of each year (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q115', '5', '5.3 Course and Exam', 41, 'To be eligible for the course, an applicant must pre-register with Health Protection Services at least:', '["Three weeks before the start of the month","Six months in advance","One week before the course","One year in advance"]', 0, 'Section 5.3 requires pre-registration at least three weeks before the start of the month (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q116', '5', '5.3 Course and Exam', 41, 'What are the exam time limit and passing grade?', '["Three hours and 85%","Three hours and 60%","Two hours and 70%","Four hours and 85%"]', 0, 'Section 5.3 grants a three-hour time limit with a passing grade of 85% (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q117', '5', '5.3 Course and Exam', 41, 'During the exam, candidates are permitted to have:', '["A smartphone","Only a pencil","The course slides and Technical Guidelines from the course handout package","Another person''s notes"]', 2, 'Section 5.3 permits candidates to have the course slides and Technical Guidelines from the handout package during the exam (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q118', '5', '5.3 Course and Exam', 41, 'A candidate who fails the exam twice must:', '["Take the course again before attempting the exam","Wait one year","Apply in another province","Pay double the fee"]', 0, 'Section 5.3 states those unsuccessful twice must take the course before again attempting the exam (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q119', '5', '5.4 Application Process', 43, 'What is the application fee for an on-site sewage disposal system approval?', '["$350","$150","$100","$400"]', 1, 'Section 5.4 sets the application fee at $150, received before assessment and non-refundable once processing starts (p.43).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q120', '5', '5.4 Application Process', 43, 'Once a complete application is received, the Inspector will complete the application assessment within:', '["12 months","Seven business days","Three business days","30 calendar days"]', 1, 'Section 5.4 requires the assessment within seven business days of receiving a complete application (p.43).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q121', '5', '5.4 Application Process', 43, 'How much written notice must the Licensee give before covering the system?', '["Seven calendar days","Three full business days via a Notice of Installation form","No notice needed","24 hours"]', 1, 'Section 5.4 requires written notice via a Notice of Installation form at least three full business days prior to covering (p.43).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q122', '5', '5.4 Application Process', 43, 'If a re-inspection is required, what fee applies?', '["$150 per re-inspection, non-refundable","$75","No fee","$400"]', 0, 'Section 5.4 sets a $150 re-inspection fee due before each re-inspection, non-refundable, also applying to non-conventional systems (p.43).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q123', '5', '5.4 Application Process', 44, 'Within ten days after the system is covered, the Licensee must provide the owner with:', '["Only a receipt","A new septic tank","Nothing","The Certificate of Compliance, a copy of the installation plan, and the operating instructions"]', 3, 'Section 5.4 requires the Certificate of Compliance, a plan copy, and operating instructions to the owner within ten days after covering, plus mailing a copy of the certificate to DPS (p.44).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q124', '5', '5.4 Application Process', 44, 'An Approval to Install expires how long after it is issued?', '["24 months","6 months","It never expires","12 months"]', 3, 'Section 5.4 gives an Approval to Install an expiry of twelve months from the date issued (p.44).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q125', '5', '5.5 Revoking an Approval to Install', 45, 'Under Regulation 2009-137, an Approval to Install may be revoked if the licensee:', '["Installs a conventional system","Makes a false statement in an application, report, return or certificate","Hires a new employee","Takes a vacation"]', 1, 'Section 5.5 allows revocation for licence term violations, PHA or Regulation violations, or false statements in applications or reports (p.45).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q126', '5', '5.5.1 Certificate of Compliance', 45, 'The Certificate of Compliance must be submitted within how many days after the system is covered?', '["10 days","30 days","7 days","3 days"]', 0, 'Section 5.5.1 requires the Certificate of Compliance within ten days after the system is covered (p.45).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q127', '6', 'Appendix A', 46, 'Installers evaluate and describe the soil texture of each soil layer in the field using:', '["The Flow Diagram for Estimating Soil Texture by Feel in Appendix A","The dosing chart","The conversion factors table","A laboratory microscope only"]', 0, 'Section 3.1 directs installers to use the Flow Diagram for Estimating Soil Texture by Feel in Appendix A (pp.8, 46).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q128', '6', 'Appendix B', 48, 'For an estimated sewage flow of 0 to 1365 L/day, what minimum septic tank working capacity does Appendix B require?', '["2000 L","3410 L","6136 L","4090 L"]', 1, 'Appendix B requires a 3410 L tank for flows of 0 to 1365 L/day (p.48).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q129', '6', 'Appendix B', 48, 'For an estimated sewage flow of 4091 to 5460 L/day in Category C soil, what total length of distribution pipe does Appendix B require?', '["235 m","330 m","175 m","400 m"]', 3, 'Appendix B requires 400 m of distribution pipe for 4091 to 5460 L/day in Category C soil (p.48).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q130', '6', 'Appendix B1', 48, 'For an estimated sewage flow of 0 to 1365 L/day, how many 4 ft x 8 ft concrete units does Appendix B1 require in Category A soil?', '["10","4","8","6"]', 3, 'Appendix B1 requires 6 concrete units for 0 to 1365 L/day in Category A soil (p.48).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q131', '6', 'Appendix C', 49, 'How deep must a test pit be under Appendix C?', '["1.8 m (6 ft)","2.4 m (8 ft)","3.0 m (10 ft)","1.2 m (4 ft)"]', 0, 'Appendix C requires the test pit to be 1.8 m (6 feet) in depth, with stepped or sloped sides (p.49).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q132', '6', 'Appendix C', 49, 'Test pits must be dug and left open until when?', '["For exactly 30 days","Until the grass grows back","Until the tank arrives","Until the Licensee receives an approval or refusal"]', 3, 'Appendix C requires test pits to remain open until the Licensee is in receipt of an approval or refusal, and to be clearly flagged (p.49).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q133', '6', 'Appendix D', 51, 'What is the peak design flow for a 3 bedroom residential unit?', '["750 L/d","1705 L/d","1365 L/d","1022 L/d"]', 2, 'Appendix D lists 1365 L/d for a 3 bedroom unit (p.51).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q134', '6', 'Appendix D', 51, 'For each bedroom beyond four, how much additional peak flow is added?', '["350 L/d per bedroom","200 L/d per bedroom","500 L/d per bedroom","750 L/d per bedroom"]', 0, 'Appendix D adds 350 L/d for each additional bedroom beyond four (p.51).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q135', '6', 'Appendix D', 52, 'What is the peak design flow for a restaurant open 24 hours on a highway?', '["125 per seat plus 75 per staff","20 per square metre","400 per seat plus 75 per staff","225 per seat plus 75 per staff"]', 2, 'Appendix D lists 400 per seat plus 75 per staff for restaurants open 24 hours on a highway (p.52).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q136', '6', 'Appendix D', 52, 'What is the peak design flow for an elementary school?', '["280 per student","30 per student","60 per student plus 75 per staff","50 per student plus 75 per staff"]', 3, 'Appendix D lists 50 per student plus 75 per staff for elementary schools (p.52).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q137', '6', 'Appendix D', 50, 'What is the minimum design flow for non-residential, commercial, industrial or institutional buildings?', '["1000 L/day","250 L/day","1365 L/day","500 L/day"]', 3, 'Appendix D sets a minimum design flow of 500 L/day, with a minimum system length of 60 m when it is used (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q138', '6', 'Appendix E', 56, 'What is the expected maximum 30-day average BOD5 of influent raw wastewater?', '["300 mg/L","150 mg/L","500 mg/L","350 mg/L"]', 0, 'Appendix E gives BOD5 of 300 mg/L, TSS of 350 mg/L, and fats, oils and greases of 35 mg/L (p.56).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q139', '6', 'Appendix E', 56, 'All systems except a lagoon must include an effluent testing port or accessible sampling location at what point?', '["Inside the house","Downstream of any required effluent filter and before discharge to the soil-based treatment component","In the distribution box only","At the well head"]', 1, 'Appendix E requires sampling downstream of any required effluent filter and prior to discharge to the soil-based treatment component (p.56).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q140', '6', 'Appendix F', 57, 'What is the sludge and scum accumulation rate for a recreational vehicle park with permanent occupation?', '["35 L/p/yr","25 L/p/yr","80 L/p/yr","48 L/p/yr"]', 2, 'Appendix F lists 80 L/p/yr for RV parks with permanent occupation (total sites x 3.5) (p.57).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q141', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the abbreviation EDSF stands for:', '["Engineered Drainage Safety Factor","Environmental Design Standard Form","Estimated Daily Sewage Flow","Estimated Drainage Soil Factor"]', 2, 'EDSF means Estimated Daily Sewage Flow. It is the single most important design number in the Guidelines: tank sizes, field lengths and lot sizes in Appendix B are all selected from the EDSF. Section 1.1 (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q142', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the abbreviation IG stands for:', '["International Gallon","Imperial gallon","Industrial Grade","In-Ground"]', 1, 'IG means Imperial gallon, the Canadian volume unit used throughout the tables (for example the 2000 IG minimum holding tank). Do not confuse it with USG, the US gallon, which is smaller. Section 1.1 (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q143', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the abbreviation NSF stands for:', '["National Safety Federation","National Standards Forum","National Sanitation Foundation","New Septic Foundation"]', 2, 'NSF is the National Sanitation Foundation. It matters because the septic tank effluent filter must meet NSF Standard 46. When an inspector asks for proof a filter complies, this is the body behind the standard. Section 1.1 (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q144', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the abbreviation CSA stands for:', '["Canadian Standards Association","Central Sanitation Agency","Canadian Safety Authority","Certified Septic Association"]', 0, 'CSA is the Canadian Standards Association. Its standards control the hardware: septic tanks must meet CSA B66 and distribution pipe must meet CSA B181/B182 series. A tank without proof of CSA compliance can be rejected. Section 1.1 (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q145', '1', '1.1 Abbreviations', 4, 'In these Guidelines, the abbreviation PID stands for:', '["Provincial Installer Document","Property Identification Number","Pipe Invert Depth","Pressure Intake Device"]', 1, 'PID means Property Identification Number, the parcel identifier used on applications and approvals so the Department ties paperwork to the right lot. Section 1.1 (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q146', '1', '1.1 Abbreviations', 4, 'In these Guidelines, L/p/yr means:', '["Load per year","Level per yard","Litres per person per year","Litres per pipe per year"]', 2, 'L/p/yr means litres per person per year. It is the unit for sludge and scum accumulation rates in Appendix F, which sizes septic tanks for non-residential uses. Section 1.1 (p.4).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q147', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 foot equals:', '["0.3048 m","3.048 m","0.3480 m","0.03048 m"]', 0, '1 ft = 0.3048 m. Field measurements in the Guidelines are given in both units, so converting correctly keeps trench depths and separation distances legal. Section 1.2 (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q148', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 litre equals how many US gallons?', '["2.640 USG","0.546 USG","0.264 USG","0.220 USG"]', 2, '1 L = 0.264 USG. Note the nearby trap: 1 L = 0.220 IG (Imperial gallons), because the Imperial gallon is larger than the US gallon. Section 1.2 (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q149', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 Imperial gallon equals how many US gallons?', '["1.50 USG","1.20 USG","0.83 USG","2.20 USG"]', 1, '1 IG = 1.20 USG. The Imperial gallon is about 20 percent larger, which is why tank volumes in IG and USG differ. Section 1.2 (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q150', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 psi equals:', '["9.807 kPa","0.145037 kPa","6.894757 kPa","6.000 kPa"]', 2, '1 psi = 6.894757 kPa. Pressure conversions matter for pump and pressure-distribution calculations in Section 4.4.7. Section 1.2 (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q151', '1', '1.2 Conversion Factors', 5, 'According to the conversion factors, 1 Imperial gallon of water weighs:', '["10 pounds","6.23 pounds","8 pounds","12 pounds"]', 0, '1 IG of water = 10 pounds. This is the handy rule behind tank sizing and uplift thinking: a 9000 L holding tank holds roughly 2000 IG, or about 20,000 pounds of sewage. Section 1.2 (p.5).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q152', '1', '1.3 Department of Public Safety (DPS), Technical Inspection Services Head Office', 6, 'What is the fax number of the DPS Technical Inspection Services Head Office?', '["(506) 457-7395","(506) 475-7394","(506) 457-7394","(506) 457-7349"]', 2, 'The head office fax is (506) 457-7394. Notices and forms may be sent by fax, so having the exact number matters when filing a Notice of Installation. Section 1.3 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q153', '1', '1.3 Department of Public Safety (DPS), Technical Inspection Services Head Office', 6, 'What is the email address of the DPS Technical Inspection Services Head Office?', '["On-site.sewagedisposal@gnb.ca","onsite@gnb.ca","sewage.disposal@gnb.ca","onsite.sewage@gnb.ca"]', 0, 'The head office email is On-site.sewagedisposal@gnb.ca. It is the contact for licensing and approval questions under Section 1.3. Section 1.3 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q154', '1', '1.3 Department of Public Safety (DPS), Technical Inspection Services Head Office', 6, 'Technical Inspection Services, which issues installer licences and system approvals, is part of which department?', '["Department of Justice","Department of Public Safety","Department of Environment and Local Government","Department of Health"]', 1, 'Technical Inspection Services sits within the Department of Public Safety (DPS). DPS handles licences and approvals, while the Department of Environment and Local Government handles watercourse permits. Section 1.3 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q155', '1', '1.3 Department of Public Safety (DPS), Technical Inspection Services Head Office', 6, 'In which city is the DPS Technical Inspection Services Head Office located?', '["Saint John","Fredericton","Woodstock","Moncton"]', 1, 'The head office is at 12 McGloin Street, Fredericton. Applications are processed through this office, and the 7-business-day assessment clock in Section 5.4 runs from when a complete application reaches it. Section 1.3 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q156', '2', '2 Introduction', 6, 'The Technical Guidelines outline the siting and technical requirements to do what in New Brunswick?', '["To build houses","To install plumbing fixtures indoors","To install, repair, construct, or replace an on-site sewage disposal system","To drill water wells"]', 2, 'The Guidelines cover siting and technical requirements to install, repair, construct, or replace on-site sewage disposal systems in the province. Everything a Licensee builds is judged against them. Section 2 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q157', '2', '2 Introduction', 6, 'What is the fundamental purpose of the information in these Guidelines?', '["To promote specific manufacturers","To set installer fees","To limit the number of installers","To ensure compliant installations and reduce risk to public health and the environment"]', 3, 'The Guidelines exist to ensure compliant installations and reduce risk to public health and the environment. Every separation distance and sizing rule traces back to this purpose. Section 2 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q158', '2', '2 Introduction', 6, 'An on-site sewage disposal system can be classified as either:', '["Gravity or electric","Temporary or permanent","Conventional or non-conventional","Residential or commercial"]', 2, 'Systems are classified as conventional or non-conventional. The classification decides which licence you need and whether an engineer must design the system. Section 2 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q159', '2', '2 Introduction', 6, 'What must Licensees follow for all parts and materials used in an installation?', '["The manufacturer''s guidelines","The cheapest available option","The homeowner''s preference","Their own judgment"]', 0, 'Licensees must follow the manufacturer''s guidelines for all parts and materials. This is why chambers, tanks and pumps must be installed per their handling and installation guides. Section 2 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q160', '2', '2 Introduction', 6, 'Approvals are issued for domestic wastewater, which includes greywater. Which of these IS covered by an approval?', '["Factory process water","Sump pump discharge","Laundry wastewater","Gutter runoff"]', 2, 'Approvals cover wastewater from personal hygiene, sanitation, cooking, laundering and similar domestic purposes, including greywater. Industrial wastes, sump pumps, gutters and runoff are excluded. Section 2 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q161', '2', '2 Introduction', 6, 'Which of the following is explicitly excluded from approval coverage?', '["Shower wastewater","Toilet wastewater","Sump pump discharge","Dishwasher wastewater"]', 2, 'Sump pump discharge is excluded from approvals, along with industrial wastes, gutters, drainage pipes and runoff water. Connecting a sump pump to a septic system can hydraulically overload it. Section 2 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q162', '2', '2 Introduction', 6, 'Which of the following may NOT be directed into an approved on-site sewage disposal system?', '["Kitchen sink wastewater","Laundry wastewater","Roof gutter runoff water","Bathroom greywater"]', 2, 'Gutters, drainage pipes and runoff water are excluded from approvals. They add clean water volume that can saturate a field without any treatment benefit. Section 2 (p.6).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q163', '2', '2.1 Engineered Systems', 7, 'An engineered system is mandatory when soil or site conditions are:', '["Ideal for a trench","Larger than one acre","Slightly sloped","Not suitable"]', 3, 'Unsuitable soil or site conditions trigger the engineered-system requirement. When the ground cannot treat effluent on its own, a Professional Engineer must design the solution. Section 2.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q164', '2', '2.1 Engineered Systems', 7, 'A pressure-dosed system is proposed. When is an engineered design NOT mandatory?', '["Never, it is always mandatory","When the lot is large","When the installer holds a non-conventional licence for such a system","When the owner requests it"]', 2, 'Non-conventional systems including pressure-dosed systems require engineered design unless the installer holds a non-conventional licence for that system. The licence proves the installer is trained for that technology. Section 2.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q165', '2', '2.1 Engineered Systems', 7, 'An engineered system is mandatory when the effluent:', '["Is purely residential","Exceeds the typical domestic wastewater strength","Comes from a single bedroom","Is low in volume"]', 1, 'Effluent stronger than typical domestic wastewater needs engineered design, because standard tables assume normal residential strength (BOD5 300 mg/L per Appendix E). Section 2.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q166', '2', '2.1 Engineered Systems', 7, 'Beyond the listed technical triggers, an engineered system is also mandatory:', '["As directed by DPS","When the installer prefers it","On weekends","For holding tanks"]', 0, 'DPS can direct that an engineered system is required even outside the listed triggers. The Department has the final say on difficult sites. Section 2.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q167', '2', '2.1 Engineered Systems', 7, 'A building has an estimated daily sewage flow of 6,000 L/d. What type of design is required?', '["An engineered system","A pit privy","No system is possible","A conventional trench system"]', 0, '6,000 L/d exceeds the 5,460 L/d threshold, so an engineered system is mandatory. The threshold exists because very large flows need professional design to protect groundwater. Section 2.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q168', '2', '2.1 Engineered Systems', 7, 'Where can more detailed licensing and approval requirements for engineered systems be found?', '["Only in the National Plumbing Code","In Regulation 2009-137 under the PHA and Section 5 of the Guidelines","In the municipal bylaws","Nowhere, they are unwritten"]', 1, 'Section 2.1 points to Regulation 2009-137 under the Public Health Act and Section 5 of the Guidelines for detailed requirements. Knowing where the law lives helps when an inspector cites it. Section 2.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q169', '2', '2.1 Engineered Systems', 7, 'Who installs an engineered on-site sewage disposal system?', '["A Licensee","Anyone with a shovel","The homeowner","A municipal employee"]', 0, 'Engineered systems must be installed by a Licensee (and designed by a Professional Engineer). Even with an engineered design, installation still requires a licensed installer. Section 2.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q170', '3', '3.1 Soil Conditions', 7, 'What is described as one of the most important deciding factors in whether a lot is suitable for a system?', '["The brand of septic tank","Soil type","The lot''s street address","The colour of the topsoil"]', 1, 'Soil type is one of the most important deciding factors in whether a lot is suitable and what the design will be. Get the soil classification wrong and the whole system sizing is wrong. Section 3.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q171', '3', '3.1 Soil Conditions', 7, 'What is necessary to appropriately assess the suitability of in-situ soils?', '["A visual examination of a test pit","A laboratory report only","A satellite photo","The owner''s description"]', 0, 'A visual examination of a test pit is required to assess in-situ soils. The pit reveals texture, structure, groundwater, bedrock and impermeable layers that no paper review can show. Section 3.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q172', '3', '3.1 Soil Conditions', 7, 'For which applications must test holes be dug?', '["Only when the owner asks","For all applications","Only for commercial lots","Only for mound systems"]', 1, 'Test holes must be dug for all applications, no exceptions. Every approval rests on a test pit assessment of the actual ground. Section 3.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q173', '3', '3.1 Soil Conditions', 7, 'Which five soil properties are examined in the test pit?', '["Texture, density, structure, depth and colour","Moisture only","Weight, price, brand, age and smell","Colour only"]', 2, 'The installer examines soil texture, density, structure, depth and colour in the test pit. Together these five observations let the Licensee predict permeability and classify the soil. Section 3.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q174', '3', '3.1 Soil Conditions', 8, 'Why does the Licensee examine texture, density, structure, depth and colour?', '["To find buried treasure","To decorate the report","To predict permeability and classify the soil","To measure the lot size"]', 2, 'Texture, density, structure, depth and colour let the Licensee predict permeability (the drainage rate) and classify the soil as A, B, C or D. Classification then drives system selection. Section 3.1 (pp.7-8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q175', '3', '3.1 Soil Conditions', 8, 'Besides soil texture, what does the test hole reveal?', '["The owner''s phone number","The presence or absence of groundwater, bedrock and impermeable soils","The price of the lot","The brand of pipe to use"]', 1, 'The test hole shows the presence or absence of groundwater, bedrock and impermeable soils. Any of these can rule out a trench and force a mound or engineered design. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q176', '3', '3.1 Soil Conditions', 8, 'What two design decisions does the test pit determine?', '["Only the colour of the soil","Whether a trench or mound is required and how much sand must be imported","The cost of the permit","The installer''s schedule"]', 1, 'The test pit determines whether an in-ground trench or raised mound field is required, and how much sand must be imported. It is the foundation of the entire design. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q177', '3', '3.1 Soil Conditions', 8, 'How do the Guidelines define bedrock?', '["Loose topsoil","Groundwater","The solid rock underlying loose materials such as gravel, sand, loam or clay","A type of sand"]', 2, 'Bedrock is the solid rock underlying loose materials such as gravel, sand, loam or clay, including limestone, sandstone and shale. Hitting bedrock limits how deep the system can go. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q178', '3', '3.1 Soil Conditions', 8, 'Which soil is named as an example of an impermeable soil?', '["Coarse sand","Loamy sand","Clay","Gravel"]', 2, 'Clay is given as the example of an impermeable soil. Because it barely drains, it cannot treat effluent and forces a mound or engineered design. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q179', '3', '3.1 Soil Conditions', 8, 'Soil categories A, B and C correspond to which appendix?', '["Appendix B","Appendix D","Appendix F","Appendix A"]', 0, 'Categories A, B and C correspond to Appendix B, the sizing tables for in-ground trench systems. Category D soils cannot use those tables. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q180', '3', '3.1 Soil Conditions', 8, 'Beyond soil texture, what else should installers consider?', '["Soil structure, density and permeability","Only the colour","The lot price","The weather"]', 0, 'Installers must determine the applicable texture but should also consider structure, density and permeability. Texture alone can mislead, especially in compacted or platy soils. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q181', '3', '3.1 Soil Conditions', 8, 'As the texture of the soil becomes more silty, what happens to permeability?', '["Decreases","Becomes infinite","Increases","Stays the same"]', 0, 'As soil texture becomes more silty, permeability decreases. This is why sands (A) drain fastest and clays (D) barely drain at all. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q182', '3', '3.1 Soil Conditions', 8, 'What is the Kfs range for Type B soil?', '["2x10-5 m/sec to 1x10-4 m/s","1x10-4 to 6x10-4 m/sec","Less than 3x10-6 m/s","3x10-6 to 2x10-5 m/s"]', 0, 'Type B spans 2x10-5 to 1x10-4 m/s. These Kfs bands are the scientific backup for the feel-based categories in Table 6. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q183', '3', '3.1 Soil Conditions', 8, 'Below what Kfs value is soil classified as Category D (too slow)?', '["Exactly 1x10-5 m/s","Below 1x10-4 m/s","Above 6x10-4 m/s","Below 3x10-6 m/s"]', 3, 'Category D (too slow) is Kfs below 3x10-6 m/s. Such soil cannot drain effluent and cannot be used to select a system. Section 3.1 (p.8) and Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q184', '3', '3.1 Soil Conditions', 8, 'Above what Kfs value is soil classified as Category D (too fast)?', '["Above 6x10-4 m/s","Exactly 2x10-5 m/s","Below 3x10-6 m/s","Between 1x10-4 and 6x10-4 m/s"]', 0, 'Category D (too fast) is Kfs above 6x10-4 m/s. Effluent races through without treatment, so these soils also cannot be used to select a system. Section 3.1 (p.8) and Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q185', '3', '3.1 Soil Conditions', 42, 'What dominant grain size defines Category A (Good) coarse and medium sands?', '["0.10 mm to 0.25 mm","1.0 mm to 2.0 mm","0.25 mm to 1.0 mm","Less than 0.10 mm"]', 2, 'Category A (Good) is coarse and medium sands with dominant grain size 0.25 mm to 1.0 mm. Grain size is the physical basis of the feel test. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q186', '3', '3.1 Soil Conditions', 42, 'When moist Category A sand is squeezed, what happens?', '["Forms a strong durable ball","Feels sticky","Will not hold together in a ball when squeezed","Forms a 3 cm ribbon"]', 2, 'Clean coarse and medium sands will not hold together in a ball or cast when squeezed moist. If it will not form a ball, you are likely looking at an A soil. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q187', '3', '3.1 Soil Conditions', 42, 'What dominant grain size defines Category B (Moderate) fine sand?', '["0.25 mm to 1.0 mm","Larger than 1.0 mm","2.5 cm or longer","0.10 mm to 0.25 mm"]', 3, 'Category B (Moderate) fine sand has dominant grain size 0.10 mm to 0.25 mm. Finer than A, it still will not hold a ball. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q188', '3', '3.1 Soil Conditions', 42, 'How does Category B loamy sand behave in the feel test?', '["A 3 cm ribbon","A shiny surface","A ball that breaks apart when handled, barely flakes, no ribbon","A strong ball surviving tossing"]', 2, 'Category B loamy sand forms a ball when squeezed but cannot be handled without breaking apart, barely forms flakes, and forms no ribbon. This in-between behaviour is the hallmark of B. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q189', '3', '3.1 Soil Conditions', 42, 'For sandy loam to count as Category B, what structure condition applies?', '["No structure requirement","Any structure at all","Only massive structure","Moderate to strongly developed structure besides platy or massive"]', 3, 'Sandy loam only qualifies for Category B under certain conditions: moderate to strongly developed structure besides platy or massive, with Kfs in the B range. Structure can disqualify an otherwise B soil. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q190', '3', '3.1 Soil Conditions', 42, 'How does Category D silt loam feel in the hand?', '["Grainy and not sticky","Floury with only slight graininess and slight stickiness","Forms a 3 cm ribbon","Shiny when rubbed"]', 1, 'D (too slow) silt loam forms a weak ball, thin flakes but no ribbons, and feels floury with slight graininess and stickiness. The floury feel is the giveaway. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q191', '3', '3.1 Soil Conditions', 42, 'How does Category D loam behave in the feel test?', '["Forms a good ball with very short ribbons under 2.5 cm","Forms ribbons over 5 cm","Will not form a ball","Feels like pure sand"]', 0, 'D (too slow) loam forms a good ball surviving moderate handling, with weak, thick, very short ribbons under 2.5 cm, feeling smooth and gritty but only slightly sticky. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q192', '3', '3.1 Soil Conditions', 42, 'Which feel-test results indicate clay (Category D)?', '["Will not hold a ball","Forms a strong durable ball, a ribbon 2.5 cm or longer, feels sticky, shines when rubbed","Forms flakes only","Feels grainy and falls apart"]', 1, 'Clay loams and clays form a strong, durable ball surviving tossing hand to hand, a medium ribbon 2.5 cm or longer, feel sticky or very sticky, and shine when rubbed on a knife blade or thumbnail. Any one of these signs means D. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q193', '3', '3.1 Soil Conditions', 42, 'Very coarse sand (Category D, too fast) consists mainly of grains:', '["0.25 mm to 1.0 mm","Less than 0.075 mm","Larger than 1.0 mm","0.10 mm to 0.25 mm"]', 2, 'D (too fast) very coarse sand is mainly grains larger than 1.0 mm with Kfs above 6x10-4 m/s. Water passes too quickly for treatment. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q194', '3', '3.1 Soil Conditions', 42, 'Gravelly sand and sandy gravel are described as soils with:', '["More gravel than sand","More sand than gravel","Mostly organic matter","Equal parts clay and silt"]', 0, 'Gravelly sand and sandy gravel have more gravel than sand. Like very coarse sand, they drain too fast for treatment and are Category D. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q195', '3', '3.1 Soil Conditions', 8, 'If soil has platy or massive structure or is very compact, what should be done?', '["Digging a deeper hole","Conducting an in-situ permeability test with a constant head permeameter","Ignoring the structure","Adding more sand"]', 1, 'Platy or massive structure, or very compact to dense soils, may not meet the permeability predicted by texture alone. A constant head permeameter test verifies the true Kfs. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q196', '3', '3.1 Soil Conditions', 8, 'Who should an installer call for more information about soil permeability testing?', '["The municipality","The well driller","The Department of Public Safety, Technical Inspection Services Head Office","A hardware store"]', 2, 'The Guidelines direct installers to call the Department of Public Safety, Technical Inspection Services Head Office for more information on permeability questions. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q197', '3', '3.1 Soil Conditions', 8, 'A permeability test returns Kfs of 1x10-5 m/s. Which soil type is this?', '["Type D","Type C","Type A","Type B"]', 3, '1x10-5 m/s falls in the Type B band (2x10-5 to 1x10-4). Matching a measured Kfs to the bands confirms or corrects the feel-test classification. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q198', '3', '3.1 Soil Conditions', 42, 'A moist sample forms a ribbon 3 cm long. How is this soil classified?', '["Category C","Category B","Category A","Category D (too slow)"]', 3, 'A medium ribbon 2.5 cm or longer signals clay, which is Category D (too slow). At 3 cm this sample is clearly D and cannot be used to select a system. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q199', '3', '3.1 Soil Conditions', 42, 'A clean sand sample has dominant grain size 0.5 mm and will not hold a ball when squeezed. Classification?', '["Category C","Category A (Good)","Cannot be classified","Category D"]', 1, 'Clean sand at 0.5 mm grain size falls in the 0.25 to 1.0 mm band, and the inability to form a ball confirms Category A (Good). Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q200', '3', '3.1 Soil Conditions', 42, 'For loamy sand to qualify as Category A, which Kfs condition must hold?', '["Kfs between 1x10-4 and 6x10-4 m/sec","Kfs below 3x10-6 m/s","Any Kfs value","No Kfs requirement"]', 0, 'Loamy sand can fall in Category A only under certain conditions, including Kfs within the A band (1x10-4 to 6x10-4 m/sec). Texture plus permeability decides. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q201', '3', '3.1 Soil Conditions', 42, 'For sandy loam to qualify as Category B, which Kfs condition must hold?', '["Any Kfs","Kfs above 6x10-4 m/s","Kfs below 3x10-6 m/s","Kfs between 2x10-5 and 1x10-4 m/s"]', 3, 'Sandy loam qualifies for Category B only with Kfs between 2x10-5 and 1x10-4 m/s. Below that it drops toward C or D. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q202', '3', '3.1 Soil Conditions', 42, 'For loam to qualify as Category C, which Kfs condition must hold?', '["Kfs between 3x10-6 and 2x10-5 m/s","Kfs below 3x10-6 m/s","Any Kfs","Kfs above 1x10-4 m/s"]', 0, 'Loam qualifies for Category C only with Kfs between 3x10-6 and 2x10-5 m/s. This is the slowest usable band before D. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q203', '3', '3.1 Soil Conditions', 8, 'What does the abbreviation KFS stand for?', '["Known field strength","Fixed filter size","Flow system key","Field saturated hydraulic conductivity"]', 3, 'KFS stands for field saturated hydraulic conductivity, the scientific measure of permeability. The Guidelines use it to define every soil category boundary. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q204', '3', '3.1 Soil Conditions', 7, 'A test pit hits solid bedrock at 1.0 m depth. What should the installer do?', '["Stop at the bedrock","Fill the hole and move on","Dig a second hole elsewhere","Keep digging to 1.8 m regardless"]', 0, 'The 1.8 m depth applies unless bedrock is encountered first. There is no point digging through solid rock, and the rock itself is the limiting factor. Section 3.1 (p.7).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q205', '3', '3.1 Soil Conditions', 42, 'Which two categories share the trait that moist sand will not hold together in a ball?', '["A and B","B and C","A and D","C and D"]', 1, 'Both Category A coarse/medium sands and Category B fine sands will not hold together in a ball when squeezed moist. The ball test alone cannot separate A from B; grain size does. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q206', '3', '3.1 Soil Conditions', 42, 'How do ribbon lengths differ between Category C sandy loam and clay?', '["C makes longer ribbons","Both are exactly 2 cm","Ribbons do not matter","1.5 to 2.5 cm versus 2.5 cm or longer"]', 3, 'Category C ribbons are very short, 1.5 to 2.5 cm, while clay (D) makes a medium ribbon 2.5 cm or longer. Ribbon length is a key field measurement. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q207', '3', '3.1 Soil Conditions', 42, 'What does a shine developing when soil is rubbed on a knife blade indicate?', '["It indicates clay (Category D)","It means nothing","It indicates gravel","It indicates Category A sand"]', 0, 'Rubbing moist soil against a hard smooth object like a knife blade or thumbnail produces a shine on clay. It is a quick confirmatory test for Category D clay. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q208', '3', '3.1 Soil Conditions', 42, 'A moist ball stays together after being tossed hand to hand several times. This indicates:', '["Clay loam or clay (Category D)","Category A sand","Category B fine sand","Topsoil"]', 0, 'A strong, durable ball that survives tossing from hand to hand several times indicates clay loam or clay, Category D. Durability separates clay from weaker loams. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q209', '3', '3.1 Soil Conditions', 42, 'Why are very coarse sands (Category D, too fast) unsuitable for selecting a system?', '["They are too expensive","They clog immediately","They treat effluent too well","Effluent passes too quickly for adequate treatment"]', 3, 'Very coarse sands let effluent pass too quickly for adequate treatment, so they are Category D and need a mound or engineered design instead of a trench. Table 6 (p.42) and Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q210', '3', '3.1 Soil Conditions', 8, 'Why is clay (Category D, too slow) unsuitable for an in-ground trench?', '["It drains too fast","It does not drain well","It contains gravel","It is too acidic"]', 1, 'Clay barely drains, so effluent cannot infiltrate and the field would pond or break out. Category D (too slow) soils need a mound or engineered design. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q211', '3', '3.1 Soil Conditions', 8, 'A test pit classifies the soil as Category D. What are the installer''s options?', '["Use a smaller tank","Dig a deeper trench","Add more distribution pipe","Use a raised mound field or engineered design"]', 3, 'Category D means the soil cannot be used to select a system at all. The options are a raised mound field or an engineered design. Section 3.1 (p.8).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q212', '3', '3.1 Soil Conditions', 42, 'What distinguishes loamy sand listed under Category A from loamy sand under Category B?', '["The required Kfs band differs between the A and B ranges","They are identical","One is always D","Only the colour differs"]', 0, 'Loamy sand sits on the A/B boundary: in A it needs Kfs in the A band, in B the B band. The permeability test, not just feel, decides which category applies. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q213', '3', '3.1 Soil Conditions', 42, 'What distinguishes sandy loam under Category B from sandy loam under Category C?', '["Only the name differs","The structure requirement and Kfs band differ","There is no difference","One is D"]', 1, 'Sandy loam in B needs moderate to strongly developed structure besides platy or massive, while in C it appears with its own Kfs band. Structure quality moves the classification. Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q214', '3', '3.1 Soil Conditions', 42, 'A sample forms a weak ball, thin flakes but no ribbons, and feels floury. Classification?', '["Fine sand, Category B","Coarse sand, Category A","Silt loam, Category D (too slow)","Sandy loam, Category C"]', 2, 'A weak ball that only stays together with careful handling, plus thin flakes and no ribbons with a floury feel, is silt loam, Category D (too slow). Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q215', '3', '3.1 Soil Conditions', 42, 'A sample forms a good ball, weak thick ribbons under 2.5 cm, and feels smooth, gritty and slightly sticky. Classification?', '["Sandy loam, Category C","Loam, Category D (too slow)","Very coarse sand, Category D (too fast)","Fine sand, Category B"]', 1, 'A good ball surviving moderate handling with very short thick ribbons under 2.5 cm, feeling smooth and gritty but only slightly sticky, is loam, Category D (too slow). Table 6 (p.42).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q216', '3', '3.2 Slope and Interceptor Drains', 9, 'How does slope affect an on-site sewage disposal system?', '["It affects the rate water moves through soil downslope of the field","It improves treatment always","It only affects the tank","It has no effect"]', 0, 'Slope affects the rate at which water from the distribution piping moves through the soil downslope of the field. Steeper slopes push effluent downhill faster, which can cause breakout. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q217', '3', '3.2 Slope and Interceptor Drains', 9, 'What limitation can slope impose?', '["Only flat lots are allowed","Slopes require bigger tanks","Slopes may limit the installation of various types of systems","Slopes never matter"]', 2, 'Slopes may limit which types of systems can be installed. A steep site that suits a trench on flat ground may need a different design. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q218', '3', '3.2 Slope and Interceptor Drains', 9, 'When is an interceptor drain required?', '["To vent gases from the tank","To measure slope angle","To distribute effluent evenly","To divert or intercept surface water and groundwater upslope of a disposal field"]', 3, 'An interceptor drain may be required to divert or intercept surface water and groundwater upslope of a disposal field. It keeps external water from overwhelming the field. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q219', '3', '3.2 Slope and Interceptor Drains', 9, 'What is a diversion ditch?', '["A soil test method","A distribution pipe","An alternative to an interceptor drain for diverting surface water","A type of septic tank"]', 2, 'A diversion ditch is the surface-water counterpart of an interceptor drain. Both keep upslope water away from the disposal field. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q220', '3', '3.2 Slope and Interceptor Drains', 9, 'What problem does an interceptor drain prevent?', '["To warm the soil","To reduce the lot size needed","To prevent saturation of the field soil during wet seasons","To speed up effluent flow"]', 2, 'The drain prevents surface and groundwater moving down the slope from saturating the field soil during wet seasons. A saturated field cannot treat effluent. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q221', '3', '3.2 Slope and Interceptor Drains', 9, 'Which waters does an interceptor drain intercept?', '["Only effluent","Both surface water and groundwater","Only rainwater","Only well water"]', 1, 'The drain handles both surface water and groundwater. Either one saturating the field will cause failure. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q222', '3', '3.2 Slope and Interceptor Drains', 9, 'Is an interceptor drain required on every installation?', '["Only for mound systems","On every lot","In certain situations","Never"]', 2, 'Interceptor drains are required only in certain situations, not on every lot. Flat, well-drained sites may not need one. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q223', '3', '3.2 Slope and Interceptor Drains', 9, 'What water movement threatens a disposal field on a slope?', '["Surface and groundwater moving down the slope toward the field","Effluent leaving the tank","Water moving up the slope","Rain falling on the house"]', 0, 'Water moving down the slope toward the field is the threat the drain addresses. Upslope placement intercepts it before arrival. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q224', '3', '3.2 Slope and Interceptor Drains', 9, 'A disposal field on a hillside ponds with water every spring from upslope seepage. What is the likely fix?', '["Move the well","Add more pipe","Install a larger tank","Install an interceptor drain or diversion ditch upslope"]', 3, 'A field ponding each spring from upslope seepage is the textbook case for an interceptor drain or diversion ditch. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q225', '3', '3.2 Slope and Interceptor Drains', 9, 'Which figure illustrates interceptor drains?', '["Figure 1","Appendix D","Figure 10","Figure 5"]', 0, 'Figure 1 in the Guidelines illustrates the interceptor drain arrangement. Figures are part of the course handout package you may use in the exam. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q226', '3', '3.2 Slope and Interceptor Drains', 9, 'When is slope considered in the process?', '["After installation","During lot evaluation, before design","Never","Only at final inspection"]', 1, 'Slope is one of the lot evaluation factors in Section 3, alongside soils, separation distances and layout. It is assessed before any design is chosen. Sections 3 and 3.2 (pp.7, 9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q227', '3', '3.2 Slope and Interceptor Drains', 9, 'Why does preventing saturation matter for treatment?', '["It increases flow","It keeps field soil unsaturated so treatment can occur","It dries the tank","It replaces the distribution box"]', 1, 'The drain keeps the field soil unsaturated so it can infiltrate and treat effluent. Treatment happens in unsaturated soil; saturated soil just passes water through. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q228', '3', '3.2 Slope and Interceptor Drains', 9, 'An interceptor drain is installed 10 m uphill from a field on a slope. Is this correct placement?', '["Inside the trench","Downslope of the field","Under the tank","Upslope of the disposal field"]', 3, 'The drain is placed upslope, between the water source and the field. Downslope placement would miss the incoming water entirely. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q229', '3', '3.2 Slope and Interceptor Drains', 9, 'When is field saturation from upslope water most likely?', '["During droughts","At night","During wet seasons","Only in winter"]', 2, 'Wet seasons bring the most upslope water, so saturation risk peaks then. The drain is specifically a wet-season protection. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q230', '3', '3.2 Slope and Interceptor Drains', 9, 'How does increasing slope change the risk to a disposal field?', '["Steeper is always better","Slope direction does not matter","Steeper slopes move water faster and may limit system choices","Slope only affects the tank"]', 2, 'Steeper slopes move water faster downslope, increasing breakout risk and potentially ruling out some system types. Gentle slopes are more forgiving. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q231', '3', '3.2 Slope and Interceptor Drains', 9, 'Which function do interceptor drains and diversion ditches share?', '["Filtering effluent","Distributing effluent","Pumping sewage uphill","Diverting water away from the field"]', 3, 'Interceptor drains and diversion ditches both divert water away from the field; neither distributes effluent. Distribution is the job of pipes, headers and boxes. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q232', '3', '3.2 Slope and Interceptor Drains', 9, 'Interceptor drains also appear in which other part of the Guidelines?', '["The exam only","The sludge rates","The lot layout assessment","The tank warranty"]', 2, 'The lot layout checklist in Section 3.4 includes interceptor drains, diversion ditches and foundation drainage. They are planned with the system, not afterthoughts. Sections 3.2 and 3.4 (pp.9, 13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q233', '3', '3.2 Slope and Interceptor Drains', 9, 'A lot is flat with no upslope water source. Is an interceptor drain still required?', '["Yes, always","No, it is only required in certain situations","Only if the owner asks","Only on flat lots"]', 1, 'A field that stays dry needs no drain; the Guidelines say a drain may be required in certain situations. Unnecessary work adds cost without benefit. Section 3.2 (p.9).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q234', '3', '3.3 Separation Distances', 10, 'From what point are disposal field separation distances measured?', '["From the centre of the field","From the septic tank","From the nearest distribution line","From the property line"]', 2, 'Disposal field distances are measured from the nearest distribution line, not the trench edge or property corner. Measure from the wrong point and the setback is wrong. Section 3.3 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q235', '3', '3.3 Separation Distances', 10, 'Compare drilled-well setbacks: which component needs the greater distance?', '["Neither needs a setback","Both need the same","The field needs the bigger setback","The tank needs the bigger setback"]', 2, 'The tank needs 15 m (50 ft) from a drilled well while the field needs 23 m (75 ft). The field gets the bigger setback because effluent leaves it. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q236', '3', '3.3 Separation Distances', 10, 'A sandpoint well is 25 m from a proposed disposal field. Does it meet the setback?', '["23 m (75 ft)","90 m (300 ft)","30 m (100 ft)","15 m (50 ft)"]', 2, 'A sandpoint well is considered a dug well for setbacks: 30 m (100 ft). Sandpoints are shallow and vulnerable to surface contamination, hence the large setback. Sections 3.3 and 3.3.2 (pp.10-11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q237', '3', '3.3 Separation Distances', 10, 'What is the disposal field setback from a body of water used as a designated potable water supply?', '["75 m (250 ft)","30 m (100 ft)","15 m (50 ft)","3 m (10 ft)"]', 0, 'For potable-supply water bodies the field needs 75 m (250 ft) while the tank needs 90 m (300 ft). Drinking water sources get the strictest setbacks in the table. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q238', '3', '3.3 Separation Distances', 10, 'What is the septic tank setback from a building foundation?', '["30 m (100 ft)","1.5 m (5 ft)","3.0 m (10 ft)","15 m (50 ft)"]', 1, 'The tank needs only 1.5 m (5 ft) from a foundation, but the field needs 3.0 m (10 ft). Effluent dispersal near foundations risks structural and drainage problems. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q239', '3', '3.3 Separation Distances', 10, 'What is the normal high water mark?', '["The visible high water mark defined under the Crown Lands and Forests Act","The property line","The lowest water level ever recorded","The middle of the lake"]', 0, 'The normal high water mark is defined under the Crown Lands and Forests Act as the visible mark where water action has distinctly marked the bed. Setbacks to water bodies are measured from this line. Section 3.3 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q240', '3', '3.3 Separation Distances', 10, 'Work is planned 20 m from a stream. What permit is required?', '["A fishing licence","A building permit only","No permit at all","A Watercourse Alteration Permit from DELG"]', 3, 'Activity within 30 m (100 ft) of a watercourse needs a Watercourse Alteration Permit from DELG. This is separate from the 15 m system setback. Table 1 footnote (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q241', '3', '3.3 Separation Distances', 10, 'The 1.2 m vertical separation to limiting factors is measured from where?', '["From the invert (bottom) of the pipe","From the ground surface","From the property line","From the tank lid"]', 0, 'The 1.2 m is measured vertically from the invert (bottom) of the pipe or pipe opening. Measuring from the trench surface would understate the separation. Table 1 footnote (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q242', '3', '3.3 Separation Distances', 10, 'Which are examples of limiting factors?', '["Trees and shrubs","Fences","Impermeable soil, groundwater table, bedrock","Driveways"]', 2, 'Limiting factors include impermeable soil, the groundwater table and bedrock. The 1.2 m buffer keeps effluent above them so soil treatment can occur. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q243', '3', '3.3 Separation Distances', 10, 'A dug well is 20 m from a proposed septic tank. Does this meet the setback?', '["Only for the tank","Only if the well is deep","No, 30 m is required","Yes, it meets it"]', 2, 'A dug well at 20 m fails the 30 m setback for both tank and field. Dug wells are shallow and easily contaminated, so the distance is large. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q244', '3', '3.3 Separation Distances', 10, 'A disposal field edge is 2 m from a house foundation. Compliant?', '["No, 3.0 m is required","Yes with a waiver","Yes","Only if the house is new"]', 0, 'The field-to-foundation setback is 3.0 m (10 ft). At 2 m the design fails and must move. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q245', '3', '3.3.1 Watercourses & Wetlands', 11, 'How do Section 3.3 setbacks relate to Clean Water Act setbacks near water?', '["The CWA 30 m work setback differs from the Section 3.3 system setbacks","The CWA has no setbacks","Section 3.3 overrides the CWA","They are identical"]', 0, 'The CWA setback for work within 30 m (100 ft) of a wetland or watercourse differs from the Section 3.3 system setbacks. Both sets of rules must be satisfied. Section 3.3.1 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q246', '3', '3.3.1 Watercourses & Wetlands', 11, 'Under the CWA, what counts as a watercourse?', '["Only lakes","Any channel, natural or artificial, whose primary function is conveying or containing water","Only rivers","Only ditches"]', 1, 'A watercourse includes rivers, creeks, streams, springs, brooks, lakes, ponds, reservoirs, canals, ditches and any channel whose primary function is conveying or containing water, flowing or not. Section 3.3.1 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q247', '3', '3.3.1 Watercourses & Wetlands', 11, 'Which of these are wetlands?', '["Cornfields","Marshes, bogs, wet meadows, peatland and swamps","Parking lots","Lawns"]', 0, 'Wetlands include marshes, bogs, wet meadows, peatland and swamps. If any of these are present, wetland rules may apply to the lot. Section 3.3.1 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q248', '3', '3.3.1 Watercourses & Wetlands', 11, 'Whose responsibility is it to confirm if a property is subject to wetland regulations?', '["The client (property owner)","No one","The tank manufacturer","The installer"]', 0, 'It is the client''s responsibility to confirm whether the property is subject to wetland regulations. The installer should flag the issue early. Section 3.3.1 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q249', '3', '3.3.2 Wells', 11, 'How does the CWA define a well?', '["A septic tank","An artificial opening in the ground for obtaining or exploring for water","A test pit","Any hole in the ground"]', 1, 'A well is an artificial opening in the ground from which water is obtained, or made for exploring for or obtaining water. Section 3.3.2 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q250', '3', '3.3.2 Wells', 11, 'How is a dug well constructed?', '["Blasting rock","Driving a pipe","Digging, manually or mechanically","Drilling with a rig"]', 2, 'A dug well is constructed by digging, manually or mechanically, under Water Well Regulation 90-79. Sandpoints, though undefined in legislation, are treated as dug wells. Section 3.3.2 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q251', '3', '3.3.2 Wells', 11, 'Why are sandpoint wells treated like dug wells for setbacks?', '["They are shallow and susceptible to surface water contamination","They are made of steel","They never run dry","They are very deep"]', 0, 'Like dug wells, sandpoints are shallow and susceptible to surface water contamination. That vulnerability is why they carry the 30 m setback. Section 3.3.2 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q252', '3', '3.3.2 Wells', 11, 'When must proof of abandoned-well decommissioning be submitted?', '["With the course registration","Along with the Notice of Installation","After the system is covered","Never"]', 1, 'Proof of decommissioning, such as a receipt or letter of intent, must be submitted along with the Notice of Installation. Without it, no approval issues. Section 3.3.2 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q253', '3', '3.3.2 Wells', 11, 'Who advises on proper decommissioning of an abandoned well?', '["The tank manufacturer","No one","The well driller only","DENV for advisement on proper decommissioning"]', 3, 'The Licensee is referred to DENV (Environment) for advisement on proper decommissioning. Decommissioning must be done right so the old well cannot channel contamination. Section 3.3.2 (p.11).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q254', '3', '3.3.3 Exemptions', 12, 'When may separation-distance exemptions be granted for lots with existing services?', '["Never","Only if the design reduces the risk of a health hazard","Automatically for old lots","Whenever the owner asks"]', 1, 'On lots with existing services, an approval may be granted only if the proposed design reduces the risk of a health hazard, confirmed by a Department risk assessment. Exemptions never increase risk. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q255', '3', '3.3.3 Exemptions', 12, 'What is the rule for separation distances on vacant lots?', '["They must be met for conventional system installations","Only property lines matter","Only well setbacks apply","They may be ignored"]', 0, 'For vacant lots, minimum separation distances must be met for conventional systems. The pre-1976 small-lot exemption is the narrow exception. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q256', '3', '3.3.3 Exemptions', 12, 'When may separation distances be reduced for non-conventional technology?', '["With pre-treatment improving effluent quality (e.g. BOD, TSS)","Never","Only for pit privies","Always, for any non-conventional system"]', 1, 'With pre-treatment such as secondary treatment after the septic tank (improving BOD, TSS), distances and lot sizes may be reduced. Cleaner effluent needs less soil buffer. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q257', '3', '3.3.3 Exemptions', 12, 'Who must stamp documentation supporting reduced setbacks for pre-treated effluent?', '["The installer","Any engineer anywhere","The homeowner","A professional engineer licensed to practice in NB"]', 3, 'The supporting documentation must be stamped by a professional engineer licensed to practice in NB. The stamp makes the engineer accountable for the claim. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q258', '3', '3.3.3 Exemptions', 12, 'What applies to separation distances for non-conventional systems WITHOUT pre-treatment?', '["They may be halved","They double","They are waived","They must be respected"]', 3, 'For non-conventional technologies without pre-treatment, such as contour and sloping sand filters, separation distances must be respected. No treatment bonus means no setback reduction. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q259', '3', '3.3.3 Exemptions', 12, 'Which appendices govern lot size and configuration requirements for vacant lots?', '["Appendix B and B1","No appendix","Appendix D","Appendix F"]', 0, 'Appendix B and B1 determine lot size and configuration for vacant lots. The tables tie lot dimensions to flow and soil permeability. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q260', '3', '3.3.3 Exemptions', 12, 'A pre-1976 lot of 3500 m2 proposes 1200 L/day. Can the exemption apply?', '["No, the cap is 750","Only with a mound","Never","Yes, if all separation distances are met"]', 3, 'At 1200 L/day the lot is under the 1365 L/day cap, so the exemption could apply if all separation distances are met. Flow and setbacks are both conditions. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q261', '3', '3.3.3 Exemptions', 12, 'Which effluent quality indicators are named for pre-treatment systems?', '["BOD and TSS","Tank size and pipe length","Colour and smell","Well depth"]', 0, 'BOD and TSS are named as the effluent quality indicators for pre-treatment. Secondary treatment after the tank improves these before soil dispersal. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q262', '3', '3.3 Separation Distances', 10, 'A lake is the designated drinking water supply for a cottage. What setbacks apply?', '["15 m for both","30 m for both","90 m for the tank and 75 m for the field","3 m for both"]', 2, 'The 90 m tank and 75 m field setbacks for potable-supply waters are far larger than the 15 m for non-potable waters. Protecting drinking water drives the strictest numbers in Table 1. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q263', '3', '3.3 Separation Distances', 10, 'The 15 m water setback has an asterisk. What does it refer to?', '["A fishing licence","Only a building permit","A Watercourse Alteration Permit is needed within 30 m","No permit is ever needed"]', 2, 'The 15 m setback for non-potable waters carries an asterisk: work within 30 m of a watercourse needs a Watercourse Alteration Permit. The setback and the permit are two different requirements. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q264', '3', '3.3 Separation Distances', 10, 'A septic tank is 2.5 m from the property line. Compliant?', '["No setback applies","2.5 m, non-compliant","3.0 m, compliant","1.5 m, compliant"]', 1, 'Property line setback is 3.0 m (10 ft) for both tank and field. At 2.5 m the tank fails and must move. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q265', '3', '3.3 Separation Distances', 10, 'A dug well is on the neighbouring lot. What setback applies to the proposed disposal field?', '["75 m","23 m","30 m","15 m"]', 2, 'Both the tank and the field need 30 m from a dug well. Neither component gets a break on well setbacks. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q266', '3', '3.3 Separation Distances', 10, 'How far must a disposal field be from a foundation drain?', '["3.0 m","30 m","15 m","1.5 m"]', 0, 'The field-to-foundation setback is 3.0 m while the tank needs only 1.5 m. The field disperses effluent, so it stays farther from structures. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q267', '3', '3.3 Separation Distances', 10, 'The 1.2 m vertical separation protects against which limiting factors?', '["Only the water table","Only clay","Impermeable soil, groundwater table and bedrock","Only bedrock"]', 2, 'The vertical 1.2 m buffer applies to impermeable soil, the groundwater table and bedrock alike. Any of these stops treatment below. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q268', '3', '3.3 Separation Distances', 10, 'What is the setback from an intermittent ditch to the disposal field?', '["No setback","15 m (50 ft)","1.5 m (5 ft)","3.0 m (10 ft)"]', 3, 'An intermittent ditch carries the same 3.0 m (10 ft) setback as a property line. Ditches can carry effluent off-site if the field is too close. Table 1 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q269', '3', '3.3 Separation Distances', 10, 'What visible feature identifies the normal high water mark?', '["The deepest point","The dock location","The property survey pin","Vegetation and soil character distinct from the bank"]', 3, 'The normal high water mark marks where water action has distinctly changed vegetation and soil character on the bed. It is the legal shoreline for setback measurement. Section 3.3 (p.10).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q270', '3', '3.3.3 Exemptions', 12, 'A pre-1976 lot of 3000 m2 proposes 1500 L/day. Can the exemption apply?', '["Yes","Yes automatically","Only with a bigger tank","No, it exceeds the 1365 L/day cap"]', 3, 'Section 3.3.3 caps the pre-1976 small-lot exemption at 1365 L/day EDSF. At 1500 L/day the lot exceeds the cap and cannot use this exemption. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q271', '3', '3.3.3 Exemptions', 12, 'Who conducts the risk assessment for a separation-distance exemption?', '["The installer","The Department","The tank supplier","The homeowner"]', 1, 'Risk assessments for exemptions are conducted by the Department. The installer proposes; the Department decides. Section 3.3.3 (p.12).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q272', '3', '3.4 Lot Layout', 13, 'Why is it important to consider everything that will eventually be on the lot?', '["To delay construction","To increase the permit fee","To avoid unnecessary cost or future limitations","To make the map pretty"]', 2, 'Lot layout planning considers everything that will eventually be on the lot to avoid unnecessary cost or future limitations. A system boxed in by later additions is expensive to fix. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q273', '3', '3.4 Lot Layout', 13, 'Which of these must be considered when assessing a lot?', '["Only the house colour","Property size and dimensions, including easements, rights of way and driveways","Only the well depth","The installer''s truck size"]', 1, 'Property size and dimensions, including easements, rights of way and driveways, must be assessed. You cannot build a field over an easement you do not control. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q274', '3', '3.4 Lot Layout', 13, 'What slope characteristics are assessed?', '["Only the colour of the grass","Percentage and direction of slope","The owner''s age","The tank brand"]', 1, 'Both percentage and direction of slope matter for layout. Direction tells you where water and effluent will travel. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q275', '3', '3.4 Lot Layout', 13, 'Which elevations must be considered in lot layout?', '["Only the basement depth","Original and expected finished ground elevations where the system is proposed","They do not matter","The roof height"]', 1, 'Original and expected finished ground elevations matter because grading changes separations to limiting factors and drainage patterns. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q276', '3', '3.4 Lot Layout', 13, 'Which wells must separation distances be checked against?', '["No wells at all","Only the owner''s well","Both the property''s wells and adjacent wells","Only abandoned wells"]', 2, 'Separations must be checked to adjacent wells too, not just the owner''s well. A neighbour''s well within the setback can kill the design. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q277', '3', '3.4 Lot Layout', 13, 'How are soil characteristics determined for lot assessment?', '["Reading the deed","Test pit inspection and, where required, hydraulic conductivity test, soil sieve analysis, or another method acceptable to the Minister","Asking the neighbour","Guessing"]', 1, 'Soil characteristics may be determined by test pit inspection and, where required, hydraulic conductivity test, soil sieve analysis or another method acceptable to the Minister. The Minister has the final say on methods. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q278', '3', '3.4 Lot Layout', 13, 'What future development must be considered in lot layout?', '["The neighbour''s dog","The price of lumber","A future swimming pool or garage","The installer''s vacation"]', 2, 'Future development such as a swimming pool or garage must be considered. Building a garage over the field later would destroy the system. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q279', '3', '3.4 Lot Layout', 13, 'How do interceptor drains and foundation drainage fit into lot layout?', '["They replace the septic tank","They are illegal","They are part of the layout assessment","They are ignored"]', 2, 'Interceptor drains, diversion ditches and the foundation drainage system are part of the layout assessment. Water management is designed with the system, not after. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q280', '3', '3.4 Lot Layout', 13, 'Which flow value is considered during lot assessment?', '["It is irrelevant to layout","The estimated daily sewage flow to be treated","Only the tank colour","The installer''s name"]', 1, 'The estimated daily sewage flow to be treated is a layout input. Flow sizes the field, and the field must fit the lot with all setbacks. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q281', '3', '3.4 Lot Layout', 13, 'Which limiting factors must be identified when assessing a lot?', '["The driveway colour","The view from the lot","Bedrock, groundwater table and impermeable soil","The mailbox location"]', 2, 'Limiting factors such as bedrock, groundwater table and impermeable soil must be identified. They decide between trench, mound or engineered designs. Section 3.4 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q282', '3', '3.5 Planning', 13, 'What does the Guidelines say about subdivisions with many houses on minimum-sized lots?', '["They are always ideal","They can be problematic, mainly over separation distances for wells and systems","They need no approvals","They are cheaper to service"]', 1, 'Subdivisions with many houses on minimum-sized lots with wells and septic systems are problematic, mainly because of separation distances. Density and on-site servicing often conflict. Section 3.5 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q283', '3', '3.5 Planning', 13, 'Who should a buyer consult before purchasing a subdivision lot for development?', '["The real estate agent only","A licensed septic system installer","No one","The tank manufacturer"]', 1, 'Potential buyers should consult a licensed septic system installer to confirm the lot suits a system, checking separations, flood plains and future development. Section 3.5 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q284', '3', '3.5 Planning', 13, 'Beyond the installer, who else must a buyer consult about a lot?', '["Only the installer","The local Municipal or Planning Authority as well","No one else","The federal government"]', 1, 'Buyers must also consult the local Municipal or Planning Authority so all laws, regulations and by-laws can be met. Septic approval is not the only permission. Section 3.5 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q285', '3', '3.5 Planning', 13, 'What should you obtain before buying an existing dwelling with an on-site system?', '["The internet provider","The previous owner''s furniture","The paint colours","Its design, condition and location"]', 3, 'A buyer of an existing dwelling with a system should obtain details on its design, condition and location before purchase. Inheriting a failed or illegal system is expensive. Section 3.5 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q286', '3', '3.5 Planning', 13, 'Which of these is named as a lot suitability concern?', '["The driveway length","The school district","Flood plains","The view"]', 2, 'Flood plains are named as a lot suitability concern for buyers. A system in a flood plain faces saturation and damage risks. Section 3.5 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q287', '3', '3.5 Planning', 13, 'Why does future development matter in planning?', '["It affects whether the lot stays suitable","It is irrelevant","It is illegal to consider","It only matters for taxes"]', 0, 'Future development is a suitability factor because later additions can crowd out the field or break setbacks. Plan the lot for its final state. Section 3.5 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q288', '3', '3.5 Planning', 13, 'What specifically makes dense subdivisions problematic?', '["Pipe brands","Required separation distances for wells and on-site systems","Grass types","Tank colours"]', 1, 'The core planning problem in dense subdivisions is the required separation distances for wells and on-site systems. Small lots struggle to fit both. Section 3.5 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q289', '3', '3.5 Planning', 13, 'Do any rules beyond these Guidelines affect lot development?', '["Rules are optional","Other regulations may also apply","No other rules exist","Only federal rules apply"]', 1, 'Other regulations may apply beyond the Guidelines, so the Municipal or Planning Authority check is mandatory. Septic rules are one layer of law. Section 3.5 (p.13).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q290', '4', '4.1 Estimated Daily Sewage Flow', 50, 'What flow must an on-site sewage disposal system be designed to handle?', '["The expected maximum sewage flow","The minimum flow","Last year''s flow","The average flow"]', 0, 'Systems must be designed for the expected maximum sewage flow, not the average. Designing for the peak prevents overload on the busiest days. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q291', '4', '4.1 Estimated Daily Sewage Flow', 14, 'When are lot dimensions and area (Appendix B) considered?', '["Once the total daily sewage flow is calculated","Never","Only for mounds","Before flow is calculated"]', 0, 'Lot dimensions and area from Appendix B are considered once total daily flow is calculated. Flow first, then check the lot can fit the resulting system. Section 4.1 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q292', '4', '4.1 Estimated Daily Sewage Flow', 50, 'What sewage must the disposal system be designed to receive?', '["All sewage from the building or structure","Only kitchen water","Only laundry water","Only toilet water"]', 0, 'The system must receive all sewage from the building. Excluding fixtures would undercount the real load. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q293', '4', '4.1 Estimated Daily Sewage Flow', 50, 'Which flows are excluded from the design flow unless otherwise approved?', '["Cooling water and roof, foundation or surface drains","Toilet wastewater","Dishwasher water","Shower water"]', 0, 'Cooling water, roof, foundation and surface drains, and water-treatment backwash are excluded unless DPS approves. They add volume without needing treatment. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q294', '4', '4.1 Estimated Daily Sewage Flow', 50, 'What is the minimum design flow for non-residential buildings?', '["500 L/day","1000 L/day","1365 L/day","100 L/day"]', 0, 'The minimum design flow for other residential, commercial, industrial and institutional buildings is 500 L/day. Small uses still get a floor so systems are not undersized. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q295', '4', '4.1 Estimated Daily Sewage Flow', 50, 'When the 500 L/day minimum design flow is used, what is the minimum system length?', '["30 m","100 m","15 m","60 m"]', 0, 'When the 500 L/day minimum is used, the minimum system length is 60 m. This matches the minimum total field length in Table 2. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q296', '4', '4.1 Estimated Daily Sewage Flow', 50, 'What period must metered flow data cover to substitute for Appendix D flows?', '["One week","Any single day","Estimates from memory","The most recent 6 to 12 months of continuous operation (or 3 full seasons)"]', 3, 'Metered data may substitute for appendix flows if it covers the most recent 6 to 12 months of continuous operation, or 3 full seasons. Short snapshots do not capture peaks. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q297', '4', '4.1 Estimated Daily Sewage Flow', 50, 'What facility must metered flow data come from?', '["A larger facility only","Any facility anywhere","A residential home always","The same or a similar facility in size, activity, location, occupancy and usage"]', 3, 'Metered data must come from the same or a similar facility in size, activity, location, hours, production, occupancy and usage pattern. A restaurant''s data cannot size a school. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q298', '4', '4.1 Estimated Daily Sewage Flow', 50, 'What safety factor is applied to metered flow data in design?', '["A 20 to 50% increase factor","A 100% decrease","Double the staff","No increase"]', 0, 'A 20 to 50 percent increase factor accommodates future growth and occasional peaks. Designing exactly to past data leaves no margin. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q299', '4', '4.1 Estimated Daily Sewage Flow', 50, 'If only average flows (no daily readings) are available, how should the design flow be adjusted?', '["Halved","Ignored","Increased by up to 100 percent","No adjustment"]', 2, 'With less than 6 to 12 months of data, or only averages, flows should be increased by up to 100 percent. Thin data gets a bigger safety margin. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q300', '4', '4.1 Estimated Daily Sewage Flow', 50, 'How do water-saving fixtures affect peak daily flow estimates?', '["Double the flow","Do not reduce peak flow estimates unless increased wastewater strength is considered","Always reduce the flow","Ignore the fixtures"]', 1, 'Water-saving fixtures must not reduce peak flow estimates unless increased wastewater strength is considered, because less water means stronger sewage needing the same treatment area. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q301', '4', '4.1 Estimated Daily Sewage Flow', 50, 'If evidence shows flows larger than the appendix values, which should be used?', '["Use the larger flows","Use the smaller flows","Split the difference","Always use the table value"]', 0, 'Design flows are recommended minimums; if larger flows exist or are expected, use the larger flows. The tables are floors, not ceilings. Appendix D (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q302', '4', '4.1 Estimated Daily Sewage Flow', 51, 'What is the peak design flow for a 1 bedroom residential unit?', '["1365 L/d","1022 L/d","500 L/d","750 L/d"]', 3, 'A 1 bedroom unit is 750 L/d. Memorizing the residential ladder (750, 1022, 1365, 1705, +350) is core exam material. Appendix D (p.51).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q303', '4', '4.1 Estimated Daily Sewage Flow', 51, 'What is the peak design flow for a 2 bedroom residential unit?', '["1705 L/d","750 L/d","1022 L/d","1365 L/d"]', 2, 'A 2 bedroom unit is 1022 L/d. Appendix D (p.51).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q304', '4', '4.1 Estimated Daily Sewage Flow', 51, 'What is the peak design flow for a 5 bedroom residential unit?', '["1365 L/d","2730 L/d","2055 L/d","1705 L/d"]', 3, 'A 4 bedroom unit is 1705 L/d, and each extra bedroom adds 350 L/d. So a 5 bedroom home is 2055 L/d. Appendix D (p.51).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q305', '4', '4.1 Estimated Daily Sewage Flow', 51, 'What is the peak flow for an assembly hall with a kitchen?', '["50 per seat","75 per seat","30 per seat","20 per seat"]', 2, 'Assembly halls with a kitchen are 30 per seat/person; without a kitchen, 20. Kitchens add wastewater load. Appendix D (p.51).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q306', '4', '4.1 Estimated Daily Sewage Flow', 51, 'What is the peak design flow for a dental office?', '["630 per bed","760 per chair plus 75 per staff","275 per practitioner","450 per bed"]', 1, 'A dental office is 760 per chair plus 75 per staff. Chairs drive the flow; staff add a per-person amount. Appendix D (p.51).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q307', '4', '4.1 Estimated Daily Sewage Flow', 51, 'What is the peak design flow for a nursing home?', '["630 per bed","450 per bed plus 75 per staff","400 per bed","275 per practitioner"]', 1, 'A nursing home is 450 per bed plus 75 per staff. Residential care has high per-bed flows. Appendix D (p.51).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q308', '4', '4.1 Estimated Daily Sewage Flow', 53, 'What is the peak design flow for a hotel or motel?', '["750 per room","320 per room","450 per room","280 per room"]', 1, 'Hotels and motels are 320 per room. Bed and breakfasts use the same 320 per room figure. Appendix D (p.53).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q309', '4', '4.1 Estimated Daily Sewage Flow', 53, 'What is the peak design flow for an office?', '["100 per employee","150 per employee","75 per employee","50 per employee"]', 2, 'An office is 75 per employee. Industrial buildings are 100 per employee with showers and 75 without. Appendix D (p.53).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q310', '4', '4.1 Estimated Daily Sewage Flow', 52, 'What is the peak design flow for a beauty salon or hairdresser?', '["2100 per station","530 per station","760 per station","650 per station"]', 3, 'A beauty salon is 650 per station. High water-use fixtures drive the number. Appendix D (p.52).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q311', '4', '4.1 Estimated Daily Sewage Flow', 52, 'What is the peak design flow for a laundromat?', '["500 per machine","1230 per machine","2100 per machine","650 per machine"]', 1, 'A laundromat is 2100 per machine, one of the highest commercial flows. Appendix D (p.52).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q312', '4', '4.1 Estimated Daily Sewage Flow', 52, 'What is the peak design flow for a daycare centre?', '["90 per child plus 75 per staff","280 per child","50 per child","350 per child"]', 0, 'A daycare centre is 90 per child plus 75 per staff. Children and staff are counted separately. Appendix D (p.52).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q313', '4', '4.1 Estimated Daily Sewage Flow', 52, 'What is the peak design flow for a dog kennel?', '["75 per enclosure plus 75 per staff","100 per enclosure","650 per enclosure","50 per enclosure"]', 0, 'A dog kennel is 75 per enclosure plus 75 per staff. Appendix D (p.52).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q314', '4', '4.2 System Sizing', 14, 'What does a conventional on-site sewage disposal system typically consist of, and how is it sized?', '["A septic tank and disposal field sized on flow and soil permeability","Any tank the owner likes","A field only","A tank only"]', 0, 'A conventional system is a septic tank plus a disposal field, sized on flow and soil permeability as estimated by test pit. Both inputs are mandatory. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q315', '4', '4.2 System Sizing', 14, 'Which soils have the greatest and least capacity to drain water?', '["Clay drains best; sand drains least","Drainage does not matter","All soils drain equally","Coarse and medium sands drain best; clay drains least"]', 3, 'Coarse and medium sands drain best; clay drains least. This drainage ranking is why soil category drives field size. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q316', '4', '4.2 System Sizing', 14, 'Why must effluent enter the soil at the right rate?', '["To keep the grass green","To allow additional treatment while preventing contamination, breakout, flooding and ponding","To save money","To meet the colour code"]', 1, 'Soil must receive effluent at a rate allowing further treatment while preventing groundwater contamination, breakout, flooding and ponding. Too fast or too slow both cause failure. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q317', '4', '4.2 System Sizing', 14, 'What is required when soil conducts water too slowly or too rapidly?', '["A smaller tank","A mound or built-up disposal field","A deeper trench","No system"]', 1, 'Soils conducting water too slowly or too rapidly need a mound or built-up field. Both extremes defeat in-ground treatment. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q318', '4', '4.2 System Sizing', 14, 'Which appendix gives disposal field sizes for soil permeability and flow?', '["Appendix A","Appendix D","Appendix F","Appendix B"]', 3, 'Appendix B gives disposal field sizes by soil permeability and flow. It is the lookup table used after the test pit and flow calculation. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q319', '4', '4.2 System Sizing', 14, 'What soil evaluation method may a Licensee employ if warranted?', '["A hydraulic conductivity test of the soil","Guess","Ask the owner","Use the neighbour''s results"]', 0, 'If the situation warrants, the Licensee may use a hydraulic conductivity test of the soil in the proposed area. Field testing beats guessing. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q320', '4', '4.2 System Sizing', 14, 'Why must the soil allow time for additional treatment?', '["To fill the tank faster","To skip the test pit","To reduce the field size to zero","To allow additional treatment of the effluent"]', 3, 'Soil must receive effluent slowly enough for additional treatment. Rushing effluent through means untreated sewage reaches groundwater. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q321', '4', '4.2 System Sizing', 14, 'What must the effluent application rate prevent?', '["Fast drainage","Green grass","Dry soil","Ponding within the disposal field"]', 3, 'Ponding within the disposal field signals the soil cannot accept the loading rate. The design rate must prevent it. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q322', '4', '4.2 System Sizing', 14, 'What estimates the soil permeability used in sizing?', '["The tank brand","The test pit assessment (or other method)","The lot price","The owner''s estimate"]', 1, 'System sizing uses the test pit assessment or another method to estimate permeability. The sizing chain is: flow, then soil, then Appendix B. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q323', '4', '4.2 System Sizing', 14, 'What failures does proper effluent application rate prevent?', '["Loud noises","High grass","Low property value","Breakout and flooding"]', 3, 'Breakout is effluent surfacing from the field, a public health hazard. Correct sizing and rate prevent it. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q324', '4', '4.2 System Sizing', 14, 'Which two inputs determine disposal field size?', '["Only the tank brand","Both estimated daily flow and soil permeability","Only the lot shape","Only flow"]', 1, 'Both flow and permeability drive size: more flow or slower soil means a bigger field. Appendix B tables show this relationship directly. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q325', '4', '4.2 System Sizing', 14, 'What contamination risk does correct soil application rate reduce?', '["Groundwater contamination","Tank corrosion","High water bills","Pump noise"]', 0, 'Groundwater contamination is the core risk the rate control addresses. Treatment in unsaturated soil protects wells and water bodies. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q326', '4', '4.2 System Sizing', 14, 'What are the two parts of a conventional system?', '["Field only","Tank only","Pump only","Tank plus disposal field"]', 3, 'A conventional system pairs the tank (primary treatment) with the field (soil treatment). Neither works alone under the Guidelines. Section 4.2 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q327', '4', '4.3 Septic Tank', 14, 'How must a septic tank be installed?', '["Tilted toward the outlet","Tilted toward the inlet","At any angle","Level, with the pad levelled first"]', 3, 'All septic tanks must be installed level, so the pad must be level before the tank is lowered. An unlevel tank disrupts compartment flow and baffles. Section 4.3 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q328', '4', '4.3 Septic Tank', 14, 'What minimum earth cover must a septic tank be designed to carry?', '["1200 mm","No cover needed","100 mm","600 mm"]', 3, 'Tanks must be designed to carry a minimum of 600 mm of earth cover, never exceeding the tank''s maximum burial depth. Too little cover risks damage; too much crushes the tank. Section 4.3 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q329', '4', '4.3 Septic Tank', 15, 'How is a siphon or pump compartment treated in tank capacity?', '["It replaces the first compartment","It is not included in the septic tank capacity","It counts double","It must be 3410 L alone"]', 1, 'The capacity of a siphon or pump compartment is not included in the septic tank capacity. Only the two treatment compartments count toward the 3410 L minimum. Section 4.3 (pp.14-15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q330', '4', '4.3 Septic Tank', 15, 'What is the watertightness requirement for septic tanks?', '["Open-topped","Slightly leaky is fine","Watertight","Porous"]', 2, 'Tanks must be watertight. Leaks let groundwater in (flooding the field) or sewage out (contamination). Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q331', '4', '4.3 Septic Tank', 15, 'What access must a septic tank provide?', '["Buried as deep as possible","Inaccessible is fine","Hidden under a deck","Accessible for septage removal with access to each compartment at or above grade"]', 3, 'Tanks must be located and buried so they are accessible for septage removal, service and maintenance, with access to each compartment at or above grade. A buried, unreachable tank cannot be pumped. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q332', '4', '4.3 Septic Tank', 15, 'The effluent filter handle should extend to within what distance of the access riser rim?', '["300 mm","50 mm","600 mm","150 mm"]', 3, 'The filter handle should extend to within 150 mm of the access riser rim and be of a material allowing easy removal and replacement. If you cannot pull the filter, you cannot maintain it. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q333', '4', '4.3 Septic Tank', 15, 'What is required for septic tank access openings?', '["Fitted with a secure lid or cover","Covered with plywood only","Left open","No requirement"]', 0, 'All access openings need secure lids or covers. Open tanks are a safety hazard and let in surface water. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q334', '4', '4.3 Septic Tank', 15, 'What is required for piping connections to the tank?', '["Loosely fitted","Watertight against infiltration and leakage","Left unsealed","Sealed with tape only"]', 1, 'All piping connections must be watertight against groundwater and surface water infiltration and wastewater leakage. Infiltration floods the system; exfiltration pollutes. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q335', '4', '4.3 Septic Tank', 15, 'What joint types are acceptable for watertight pipe joints?', '["Dry-stacked with no seal","Solvent cement joint, mechanical joint, or manufacturer-approved","No requirement","Tape only"]', 1, 'All pipe joints from the building to the tank and from the tank through the header must be watertight, using solvent cement, mechanical joints or manufacturer-approved methods. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q336', '4', '4.3 Septic Tank', 15, 'Can a deck be built over a septic tank?', '["It is required","It should not be done","It voids the warranty only","It is encouraged"]', 1, 'Decks or other structures that limit access should not be built over septic tanks or pump chambers. Future pumping and service need clear access. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q337', '4', '4.3 Septic Tank', 15, 'What limits how deep a septic tank may be buried?', '["The water table","The property line","The frost line","The suction elevation of vacuum trucks"]', 3, 'Tank depth must not exceed the suction elevation of vacuum trucks, or the pumper cannot empty the tank. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q338', '4', '4.3 Septic Tank', 15, 'How must septic tanks be protected from surface loads?', '["They must be driven over weekly","They must be protected from overhead loads beyond their capacity","They need no protection","Loads do not matter"]', 1, 'Tanks must be protected from overhead loads greater than their load-bearing capability. Driving over a tank can collapse it. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q339', '4', '4.3 Septic Tank', 15, 'When must septic tanks be secured against hydraulic uplift?', '["Never","Only for steel tanks","In areas with potential for high groundwater levels","Only on hills"]', 2, 'Tanks may need securing against hydraulic uplift where high groundwater is possible. An empty tank can float out of the ground. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q340', '4', '4.3 Septic Tank', 15, 'Which plumbing code is referenced for pipe details?', '["The US plumbing code","The installer''s handbook","The most recent National Plumbing Code of Canada used by DPS","No code applies"]', 2, 'The Guidelines refer to the most recent National Plumbing Code of Canada used by DPS for pipe details. Plumbing code compliance is part of the installer''s job. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q341', '4', '4.3 Septic Tank', 15, 'Is compaction of bedding material under inlet and outlet piping required?', '["It is prohibited","Only for the outlet","It is optional","It is essential to support the piping"]', 3, 'Compaction of bedding under inlet and outlet piping is essential to support the piping. Settling pipes shear off at the tank wall. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q342', '4', '4.3 Septic Tank', 16, 'What about the manufacturer''s placing and backfilling instructions?', '["Only the price matters","Backfill with clay","They must be followed, and may include pea gravel","They may be ignored"]', 2, 'Manufacturer instructions for placing and backfilling, which may include pea gravel, must be followed. Each tank design has specific bedding needs. Section 4.3 (p.16).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q343', '4', '4.3 Septic Tank', 16, 'What can happen to an empty septic tank under high water table conditions?', '["Nothing happens","They crack immediately","They can lift out of the ground","They sink"]', 2, 'Empty tanks have been known to lift out of the ground under high water table conditions, so they must be secured against uplift. Section 4.3 (p.16).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q344', '4', '4.3 Septic Tank', 16, 'What happens to a two-piece tank with damaged joining edges?', '["Rejected and removed from the installation","Accepted with a discount","Patched with tape","Buried deeper"]', 0, 'Two-piece tanks with damaged joining edges or improper caulking will be rejected and removed. A bad joint is a guaranteed leak. Section 4.3 (p.16).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q345', '4', '4.3 Septic Tank', 16, 'Where is information on septic tank sludge and scum accumulation rates?', '["Appendix A","Appendix D","Appendix F","Appendix C"]', 2, 'Appendix F holds sludge and scum accumulation rates used to size tanks for non-residential uses. Residential tanks use the Appendix B minimums. Section 4.3 (p.16).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q346', '4', '4.3 Septic Tank', 15, 'How accessible must the effluent filter be?', '["Easily accessible for maintenance","Sealed permanently inside","Removed after one year","Optional"]', 0, 'The effluent filter must be easily accessible for maintenance per manufacturer guidelines. A filter you cannot reach will never be cleaned. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q347', '4', '4.3 Septic Tank', 15, 'What material requirement applies to the filter handle?', '["A material allowing easy removal and replacement","Wood only","Any scrap material","No handle needed"]', 0, 'The handle should be of a material allowing easy removal and replacement. Corroded or flimsy handles defeat maintenance. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q348', '4', '4.3 Septic Tank', 15, 'Besides capacity and burial depth, what does the CSA standard specify?', '["Only the price","The delivery method","Only the colour","Inlet and outlet connections, air space, and access openings"]', 3, 'CSA B66 also specifies inlet and outlet connections, air space and access openings. The standard covers the whole tank, not just strength. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q349', '4', '4.3 Septic Tank', 15, 'Which figure illustrates the interior of a septic tank?', '["Figure 6","Figure 10","Figure 2","Figure 1"]', 2, 'Figure 2 illustrates a septic tank interior, showing baffles and compartments. Figures are part of the handout package allowed in the exam. Section 4.3 (p.15).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q350', '4', '4.3 Septic Tank', 14, 'The CSA stamp on a tank is not visible. What may the Licensee be required to do?', '["Provide proof the tank conforms to the CSA standard","Use a smaller tank","Install it anyway","Paint over it"]', 0, 'If the CSA stamp is unclear or not visible, the Licensee may have to prove the tank conforms. No proof means no approval. Section 4.3 (p.14).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q351', '4', '4.4.1 Pipe and Stone In-ground Trench', 18, 'In which soils may an in-ground trench field be built?', '["In A, B or C soil where conditions permit","In any soil","Only in clay","Only in Category D"]', 0, 'In-ground trenches suit A, B or C soils where in-situ conditions permit. Soil category is checked first in lot evaluation. Section 4.4.1 (p.18).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q352', '4', '4.4.1 Pipe and Stone In-ground Trench', 18, 'In-ground trenches are dug into what?', '["Into original ground","Into bedrock","Above ground","Into imported fill"]', 0, 'Trenches are dug into original ground, not fill. Undisturbed native soil has the tested permeability the design relies on. Section 4.4.1 (p.18).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q353', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'Where is clean crushed rock placed relative to the distribution pipe?', '["Only over the pipe","Only under the pipe","Both under and over the perforated pipe","No rock is used"]', 2, 'Clean crushed rock goes both under and over the perforated pipe. The rock bed distributes effluent and protects the pipe. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q354', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'Which standards must perforated distribution pipe meet?', '["CAN/CSA B181.1, B181.2, B182.1 and B182.2","No standard applies","CSA B66","NSF Standard 46"]', 0, 'Distribution pipe must meet CAN/CSA B181.1, B181.2, B182.1 and B182.2. Non-compliant pipe can collapse or leach. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q355', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What is done with the ends of distribution lines in a trench field?', '["Connected to the well","Left open","Capped","Vented to air"]', 2, 'Distribution line ends are capped in a trench field so effluent stays in the pipe and rock bed. Open ends would short-circuit the field. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q356', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What is the maximum trench depth?', '["900 mm (36 in)","450 mm (18 in)","1200 mm (48 in)","600 mm (24 in)"]', 0, 'Maximum trench depth is 900 mm (36 in). Deeper trenches get too close to limiting factors. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q357', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What is the trench separation, centre to centre?', '["1.5 m (5 ft)","1.0 m (3 ft)","6.0 m (20 ft)","3.0 m (10 ft)"]', 0, 'Trenches are separated 1.5 m (5 ft) centre to centre. Spacing prevents overlapping saturated zones. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q358', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What size of crushed stone is required?', '["5 mm to 10 mm","50 mm to 100 mm","Sand only","10 mm to 50 mm"]', 3, 'Crushed stone must be 10 mm to 50 mm (1/2 in to 2 in). Correct stone size keeps voids open for effluent flow. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q359', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What are the requirements for the top header in the field?', '["Non-perforated and level","Perforated and level","Non-perforated and sloped","Perforated and sloped"]', 0, 'The top header in the field is non-perforated and level. It feeds the perforated laterals without leaking effluent along its length. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q360', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'How much topsoil must the cover layer include at minimum?', '["60 cm (24 in)","10 cm (4 in)","5 cm (2 in)","30 cm (12 in)"]', 1, 'The cover needs at least 10 cm (4 in) of topsoil to support vegetation. Vegetation prevents erosion and aids evapotranspiration. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q361', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'How should the cover be finished?', '["Left as bare dirt","Paved over","Finished with sod or seed","Covered with plastic"]', 2, 'The cover is finished with sod or seed to prevent erosion and aid in evapotranspiration. Bare soil over a field erodes and seals. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q362', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'Why must the soil cover allow air to permeate?', '["To add weight","To keep it warm","To look nice","To allow air to permeate"]', 3, 'The soil cover must allow air to permeate because the treatment zone needs oxygen. Sealed covers suffocate the biology. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q363', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What does a trench field consist of?', '["A single long pipe","Several individual trenches with equal distribution","A holding tank","One deep pit"]', 1, 'A trench field uses several individual trenches with one or more level headers for equal distribution, or a distribution box. Equal loading prevents overloading one trench. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q364', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'Where are trench construction details illustrated?', '["Table 1","Table 5","Appendix D","Table 2 and Figures 4 and 5"]', 3, 'Table 2 and Figures 4 and 5 detail trench construction. The figures are in the handout package you may bring to the exam. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q365', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'After the perforated pipe is laid and graded, what covers it?', '["Left exposed","Filled with sand","Covered with clean crushed rock","Covered with clay"]', 2, 'The perforated pipe is also covered with clean crushed rock after laying. Rock above and below gives full-perimeter drainage. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q366', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What if the soil cover exceeds 60 cm (24 in)?', '["It needs alternative means of aeration","It is prohibited entirely","It is always fine","It needs a bigger tank"]', 0, 'Cover over 60 cm needs alternative aeration because deep cover blocks air permeation. Treatment needs oxygen throughout the cover depth. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q367', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'How must effluent be distributed among trenches?', '["Equal distribution","All flow to one trench","Random distribution","No distribution needed"]', 0, 'Equal distribution across trenches is the design goal, via level headers or a distribution box. Uneven loading overloads one trench and starves others. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q368', '4', '4.4 Conventional Design', 17, 'What may be used instead of a level header to ensure equal loading?', '["A deeper trench","A distribution box","A pump","A larger tank"]', 1, 'A distribution box may replace the level header between tank and gravity field to load all lines equally. Both methods achieve equal distribution. Section 4.4 (p.17).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q369', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What is the minimum soil cover over a trench field?', '["60 cm (24 in)","30 cm (12 in)","90 cm (36 in)","10 cm (4 in)"]', 1, 'The 30 cm minimum cover protects the field while letting air through. It is the same minimum used for chamber fields. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q370', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'Why should the cover support vegetation?', '["It feeds the tank bacteria","It aids in evapotranspiration","It looks nice","It is required by law for appearance"]', 1, 'Sod or seed aids evapotranspiration, which removes water from the field through plants. Vegetation is part of the water balance. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q371', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'A trench has 200 mm of stone under the pipe. How much stone goes over the pipe?', '["300 mm under / 300 mm over","50 mm under / 200 mm over","100 mm under / 100 mm over","200 mm under / 50 mm over"]', 3, 'The 200 mm under / 50 mm over split gives a deep drainage bed below and a thin protective layer above. Both dimensions are inspected. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q372', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'A 50 ft lateral needs what total fall?', '["4 in per 50 ft","Level","2 in per 50 ft","1 in per 100 ft"]', 2, 'At 2 in per 50 ft the pipe matches the required 50 mm per 15 m slope. Too flat ponds effluent; too steep rushes it to the far end. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q373', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'A design calculates 45 m of trench. What is the minimum allowed total field length?', '["60 m","30 m","120 m","90 m"]', 0, 'The 60 m minimum matches the Appendix D minimum system length for 500 L/day flows. Small systems still need this floor. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q374', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'A trench is dug 12 in wide. Does it meet the minimum width?', '["18 in","24 in","12 in","36 in"]', 0, 'The 18 in minimum width gives room for pipe plus sidewall infiltration area. Narrower trenches shortchange treatment. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q375', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'A designer proposes a 60 ft trench. What is the maximum trench length?', '["100 ft","No maximum","50 ft","200 ft"]', 0, 'The 50 ft maximum keeps each lateral short enough for even distribution. Longer lines overload the far end. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q376', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'A trench is excavated 40 in deep. Compliant?', '["Yes","Only with a waiver","Yes if the soil is sand","No, 36 in is the maximum"]', 3, 'At 36 in maximum depth, a 40 in trench is too deep and risks hitting limiting factors. Depth is measured and enforced. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q377', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What surrounds the perforated pipe in the trench?', '["Clay lumps","1/2 in to 2 in stone","Sand","6 in boulders"]', 1, 'Stone from 1/2 in to 2 in keeps voids open. Finer material would clog; larger is unnecessary. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q378', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'An installer uses perforated pipe for the top header. Is this correct?', '["Non-perforated and level","Perforated and sloped","It does not matter","There is no header"]', 0, 'The header must be non-perforated so it conveys, not disperses, and level so each lateral gets equal flow. Table 2 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q379', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'What does finishing the cover with sod or seed prevent?', '["Erosion","Weight","Warmth","Colour"]', 3, 'Sod or seed prevents erosion of the cover. Eroded cover exposes the field and seals the surface. Section 4.4.1 (p.19).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q380', '4', '4.4.2 Raised Mound Trench System', 21, 'What does adding imported sand achieve in a mound system?', '["To look nice","To increase the distance from the pipe invert to the limiting factor","To avoid permits","To reduce the field size"]', 1, 'The mound increases the distance from the pipe invert to the limiting factor by adding imported sand. That restored separation is what makes treatment possible on poor sites. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q381', '4', '4.4.2 Raised Mound Trench System', 21, 'Which of these is a limiting factor that can force a mound?', '["Bedrock","Flat ground","Large lots","Deep sand"]', 0, 'Bedrock is a named limiting factor. Shallow rock leaves no room for treatment below a trench. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q382', '4', '4.4.2 Raised Mound Trench System', 21, 'Which water condition is a limiting factor?', '["Wind","Cold winters","Seasonal high water table","Dry summers"]', 2, 'Seasonal high water table is a named limiting factor. When water rises seasonally, the vertical buffer disappears. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q383', '4', '4.4.2 Raised Mound Trench System', 21, 'Which soil condition forces a mound?', '["Topsoil","Loamy sand","Impermeable soil such as clay","Category A sand"]', 2, 'Impermeable soil like clay is a limiting factor. It cannot accept effluent at a usable rate. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q384', '4', '4.4.2 Raised Mound Trench System', 21, 'Why are very coarse, gravelly sands limiting factors?', '["They drain too fast for adequate treatment","They contain clay","They drain too slowly","They are too expensive"]', 0, 'Very coarse and gravelly sands drain too fast for treatment, making them limiting factors. Fast is just as bad as slow. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q385', '4', '4.4.2 Raised Mound Trench System', 21, 'If part of the in-situ soil is used to build the mound, how is the system sized?', '["The system is sized on its A, B or C classification","It is always Category A","It is ignored","Sizing is skipped"]', 0, 'If in-situ soil forms part of the mound, the system is sized on that soil''s A, B or C classification. Only usable soil counts toward sizing. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q386', '4', '4.4.2 Raised Mound Trench System', 21, 'What does scarification mean?', '["Paving the area","Loosening soil to prevent smearing while maintaining structure","Removing all soil","Compacting the soil hard"]', 1, 'Scarification means loosening and breaking up soil to prevent smearing while maintaining soil structure. Smearing would seal the surface against effluent. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q387', '4', '4.4.2 Raised Mound Trench System', 21, 'Which implements are recommended for scarifying?', '["A bulldozer blade","A chainsaw","A lawnmower","A cultivator, mould board plough, or chisel plough"]', 3, 'A cultivator, mould board plough or chisel plough should be used. These break up soil without smearing it. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q388', '4', '4.4.2 Raised Mound Trench System', 21, 'Why is scarification necessary?', '["To help effluent pass into the native soil","To make it pretty","To kill weeds","To mark boundaries"]', 0, 'Scarification helps effluent pass into the native soil. Without it, the mound sand and native soil do not connect hydraulically. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q389', '4', '4.4.2 Raised Mound Trench System', 21, 'How is imported sand placed for a mound?', '["Placed level with the top of the proposed trench, then trenched with a level bottom","Mixed with clay","Dumped in a pile","Spread thinly anywhere"]', 0, 'Imported sand should sit level with the top of the proposed trench, then the trench is excavated into the sand with a level bottom in both width and length. This guarantees the designed sand depth below the field. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q390', '4', '4.4.2 Raised Mound Trench System', 21, 'How must the trench bottom be graded in a mound?', '["Sloped toward the outlet","Level in both width and length","V-shaped","It does not matter"]', 1, 'The trench bottom must be level in both width and length. Level trenches distribute evenly; tilted ones do not. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q391', '4', '4.4.2 Raised Mound Trench System', 21, 'Why must sand lifts not exceed 300 mm?', '["It looks bad","It drains too fast","It may settle after placement","It costs more"]', 2, 'Sand placed in lifts over 300 mm can settle after placement, changing depths and separations. Thin lifts compact uniformly. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q392', '4', '4.4.2 Raised Mound Trench System', 21, 'How are distribution line ends handled in gravity-fed mound beds?', '["Removed","Connected with solid or perforated pipe, level","Left open","Capped always"]', 1, 'In gravity-fed beds the line ends are connected with solid or perforated pipe so as to be level. Connected ends balance the lines. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q393', '4', '4.4.2 Raised Mound Trench System', 21, 'How are line ends handled on sloped mounds?', '["Always connected","Capped unless pipes are on the same level, then connected","Left open","Always removed"]', 1, 'For sloped mounds the ends must be capped unless the pipes are on the same level, in which case they are connected. Level pipes can share flow; sloped ones cannot. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q394', '4', '4.4.2 Raised Mound Trench System', 21, 'Is perforated pipe used to connect line ends counted in the system length?', '["Not counted in total linear length","Counted double","Always counted","Counted as half"]', 0, 'Perforated connector pipe must be surrounded by clean crushed rock and is not counted in the total linear system length. Only true dispersal length counts. Section 4.4.2 (p.21).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q395', '4', '4.4.2.1 Imported Sand', 22, 'What percent must pass the 9.5 mm sieve for imported sand?', '["0 to 10%","50 to 60%","80 to 100%","100% exactly"]', 2, 'The 9.5 mm sieve must pass 80 to 100 percent. This caps the coarse fraction so the sand is not too gravelly. Table 3 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q396', '4', '4.4.2.1 Imported Sand', 22, 'What percent must pass the 4.75 mm (No. 4) sieve?', '["80 to 100%","50 to 60%","Exactly 50%","Less than 8%"]', 0, 'The 4.75 mm sieve must pass 80 to 100 percent. Together with the 9.5 mm requirement, this defines the sand as sand, not gravel. Table 3 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q397', '4', '4.4.2.1 Imported Sand', 22, 'Can sandstone be assumed suitable as imported sand?', '["It is the best source","It is required","It does not typically meet the requirements","It always meets them"]', 2, 'Sandstone does not typically meet the sand requirements. Rock type matters as much as grain size. Section 4.4.2.1 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q398', '4', '4.4.2.1 Imported Sand', 22, 'What happens when imported sand contains too many fines?', '["It drains too fast","It looks bad","It clogs and cannot accept effluent at an acceptable rate","It is too cheap"]', 2, 'Too many fines (clay and silt) clog the sand so it cannot accept effluent at an acceptable rate. Fines are the enemy of mound sand. Section 4.4.2.1 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q399', '4', '4.4.2.1 Imported Sand', 22, 'What happens when imported sand is too coarse?', '["It costs less","It clogs","It is perfect","Effluent passes too quickly for acceptable treatment"]', 3, 'Too-coarse material lets effluent pass too quickly for acceptable treatment. Both extremes fail. Section 4.4.2.1 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q400', '4', '4.4.2.1 Imported Sand', 22, 'Which sands give the most consistent gradation results?', '["River silt","Manufactured crushed or screened sands","Beach sand","Pit-run bank sand"]', 1, 'Pit-run sand dug from the bank can vary, while manufactured crushed or screened sands give the most consistent results. Consistency is why testing matters. Section 4.4.2.1 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q401', '4', '4.4.2.1 Imported Sand', 22, 'How is compliance with Table 3 determined?', '["Tasting it","Sieve analysis or a permeability test","Looking at it","Weighing the truck"]', 1, 'Compliance is shown by sieve analysis (grain size, D10, Cu) or a permeability test for KFS. One of the two proves the sand meets Table 3. Section 4.4.2.1 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q402', '4', '4.4.2.1 Imported Sand', 23, 'What is D10 (effective size)?', '["The truck capacity","The average colour","The largest particle size","The size below which 10% of the sample by weight is finer"]', 3, 'D10 is the particle size below which 10 percent of the sample by weight is finer. A smaller D10 means more fines and likely lower permeability. Section 4.4.2.1 (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q403', '4', '4.4.2.1 Imported Sand', 23, 'What does Cu indicate?', '["Cubic volume","Copper content","Compaction units","The range of particle sizes in the sand fraction"]', 3, 'Cu is the uniformity coefficient, the range of particle sizes in the sand fraction. A higher Cu means a wider range and generally lower permeability as small particles fill voids. Section 4.4.2.1 (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q404', '4', '4.4.2.1 Imported Sand', 23, 'What does a high Cu number generally mean for permeability?', '["Lower permeability","No change","Higher strength","Higher permeability"]', 0, 'A high Cu means small particles fill voids between medium ones, lowering permeability. Well-graded sand drains slower than uniform sand. Section 4.4.2.1 (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q405', '4', '4.4.2.1 Imported Sand', 23, 'What does KFS stand for?', '["Field saturated hydraulic conductivity","Known filter size","Fixed flow standard","Filter sand"]', 0, 'KFS is field saturated hydraulic conductivity, the scientific expression of permeability. The Guidelines define every soil and sand limit in KFS. Section 4.4.2.1 (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q406', '4', '4.4.2.1 Imported Sand', 23, 'Which is an accepted method to determine KFS of imported sand?', '["A pH strip","Constant head permeameter in a representative bed","Guessing","A tape measure"]', 1, 'KFS can be found by field permeability with a constant head permeameter in a representative bed, a simplified falling head test, or lab testing. Three accepted methods cover field and lab. Section 4.4.2.1 (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q407', '4', '4.4.2.1 Imported Sand', 22, 'What if delivered sand fails the specification after placement?', '["It is never needed","It is time-consuming and expensive","It is cheap and easy","It improves the sand"]', 1, 'Removing and replacing bad sand is time-consuming and expensive, so confirming suitability before delivery saves the job. Prevention beats replacement. Section 4.4.2.1 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q408', '4', '4.4.2.1 Imported Sand', 22, 'What sand is required with plastic infiltrative chambers?', '["Table 3 sand only","Any sand","Sand meeting the manufacturer''s specifications","No sand"]', 2, 'For plastic chambers, sand meeting the manufacturer''s specifications must be used, not necessarily Table 3 sand. Chamber makers certify their own media. Section 4.4.2.1 (p.22).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q409', '4', '4.4.2.2 Apron and Taper', 23, 'Why is apron design crucial in mound fields?', '["To mark the lot line","To reduce sand use","To look nice","To minimize breakout at the sides"]', 3, 'The apron minimizes breakout at the mound sides. The 6 m downslope width handles the main flow direction; 3 m suffices elsewhere. Section 4.4.2.2 (p.23).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q410', '4', '4.4.2.2 Apron and Taper', 24, 'How is the apron sand buffer built before the taper?', '["The buffer is vertical","The sand buffer extends 3 m (6 m downslope), then the 4:1 taper begins","The taper starts immediately","No buffer is used"]', 1, 'The sand buffer extends horizontally from the trench end (3 m, or 6 m downslope), then the 4:1 taper begins. The buffer plus taper contain lateral flow. Section 4.4.2.2 (pp.23-24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q411', '4', '4.4.2.2 Apron and Taper', 24, 'Where does the absorption area begin?', '["At the lot line","At the tank outlet","At the ground surface","At the pipe invert or equivalent"]', 3, 'The absorption area begins at the pipe invert or equivalent. All vertical separations are measured from this plane. Section 4.4.2.2 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q412', '4', '4.4.2.2 Apron and Taper', 24, 'How much gravel is placed over the pipe in a mound?', '["200 mm","100 mm","25 mm","50 mm (2 in)"]', 3, '50 mm (2 in) of gravel goes over the pipe before backfill. The gravel protects the pipe and aids distribution. Section 4.4.2.2 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q413', '4', '4.4.2.2 Apron and Taper', 24, 'How much topsoil must finish the mound surface?', '["50 mm","100 mm minimum","No topsoil needed","200 mm"]', 1, 'The top 100 mm minimum must be topsoil finished with sod or seed to prevent erosion and aid evapotranspiration. Vegetation completes the mound surface. Section 4.4.2.2 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q414', '4', '4.4.2.2 Apron and Taper', 24, 'Which figure shows a typical mound system?', '["Figure 10","Figure 4","Figure 6","Figure 2"]', 2, 'Figure 6 overviews a typical mound system. Figures are in the handout package allowed during the exam. Section 4.4.2.2 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q415', '4', '4.4.2.2 Apron and Taper', 24, 'Where does the 4:1 taper begin?', '["It begins at the end of the apron and slopes to finished grade","It is vertical","There is no taper","It starts at the pipe"]', 0, 'The 4:1 taper slopes from the apron end to match finished grade, then continues upward to the finished elevation. The taper sheds water without eroding. Section 4.4.2.2 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q416', '4', '4.4.2.2 Apron and Taper', 24, 'How is the mound completed above the apron?', '["It is paved","It is left open","The 4:1 taper extends upward from the apron end to finished elevation","It is abandoned"]', 2, 'The mound is completed by extending the 4:1 taper upward from the apron end to the finished elevation. The full cross-section is sand buffer, taper, and topsoil cap. Section 4.4.2.2 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q417', '4', '4.4.3 Leaching Chamber (Concrete)', 24, 'What do concrete leaching chambers replace?', '["Pumps","Septic tanks","Distribution boxes","Perforated pipe and stone in distribution lines"]', 3, 'Concrete leaching chambers replace perforated pipe and stone in distribution lines. They are an approved alternative dispersal method. Section 4.4.3 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q418', '4', '4.4.3 Leaching Chamber (Concrete)', 24, 'What biological process occurs inside leaching chambers over time?', '["The units dissolve","A clogging mat develops, giving long-term permeability similar to other systems","It ruins the system","Nothing happens"]', 1, 'A clogging mat develops in the units, giving long-term permeability similar to other systems. The mat is part of normal biological treatment. Section 4.4.3 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q419', '4', '4.4.3 Leaching Chamber (Concrete)', 24, 'What pipe arrangement do leaching chambers require?', '["A vertical pipe only","A perforated pipe through the length, capped at the end","No pipe at all","A solid pipe with no cap"]', 1, 'Each unit needs a perforated pipe through its length, capped at the end, to distribute effluent along the chamber. Section 4.4.3 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q420', '4', '4.4.3 Leaching Chamber (Concrete)', 24, 'How are leaching chambers installed level?', '["Concrete blocks","Sufficient Table 3 sand under each unit","Wood shims","Nothing"]', 1, 'Units are levelled by placing sufficient Table 3 sand under each one. Level chambers distribute evenly. Section 4.4.3 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q421', '4', '4.4.3 Leaching Chamber (Concrete)', 24, 'Which classification system defines the coarse gravel size?', '["The Unified Soil Classification System","The plumbing code","The installer''s judgment","No system"]', 0, 'Coarse gravel follows the Unified Soil Classification System at 19 to 76 mm. Using the standard classification avoids disputes over what coarse means. Section 4.4.3 (p.24).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q422', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'Why must the sand under concrete chambers be compacted?', '["It is not needed","To prevent settling of the heavy units","To save sand","To speed up work"]', 1, 'Because the concrete units are heavy, compacting the sand prevents settling that would tilt the chambers. Section 4.4.3 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q423', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What is the minimum trench width for leaching chambers?', '["450 mm","6 m","2 m (6 ft)","1.5 m"]', 2, 'Table 4 requires minimum trench width 2 m (6 ft) for chambers, wider than the 450 mm pipe trench, because the units are 1.2 m wide. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q424', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What is the maximum trench depth for leaching chambers?', '["600 mm","450 mm","1200 mm","900 mm (36 in)"]', 3, 'Maximum trench depth is 900 mm (36 in), the same as pipe trenches, keeping the system above limiting factors. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q425', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What is the maximum trench length for leaching chambers?', '["30 m","60 m","10 m","15 m (50 ft)"]', 3, 'Maximum trench length is 15 m (50 ft), matching pipe trenches for even distribution. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q426', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What is the trench separation for leaching chambers?', '["3 m","1.5 m","15 m","6 m (20 ft)"]', 3, 'Trench separation is 6 m (20 ft) centre to centre, wider than pipe trenches because each row is a full chamber width. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q427', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What is the minimum total field length for a chamber field?', '["10 units","6 units","60 m","3 units"]', 1, 'Minimum total field length is 6 units. Chamber fields are counted in units, not metres of pipe. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q428', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'How much crushed rock is required on the sides of the galleys?', '["300 mm (12 in)","600 mm","100 mm","No rock"]', 0, '300 mm (12 in) of crushed rock goes on the sides of the galleys. Side rock gives the chambers lateral infiltration area. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q429', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What slope do leaching chamber galleys require?', '["V-shaped","Sloped 5%","Sloped 2%","Level"]', 3, 'Galleys are installed level so effluent spreads evenly along the row. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q430', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What are the top header requirements for a chamber field?', '["Perforated and level","Perforated and sloped","There is no header","Non-perforated and level"]', 3, 'The top header is non-perforated and level, same as pipe systems, to feed rows equally without dispersing. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q431', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'What is the required depth to the limiting factor from the bottom of the infiltrator?', '["0.5 m","1.2 m","1.8 m","1 m (3 ft)"]', 3, 'Depth to the limiting factor from the bottom of the infiltrator is 1 m (3 ft). Chamber bottoms sit lower than pipe inverts, so the rule is explicit. Table 4 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q432', '4', '4.4.3 Leaching Chamber (Concrete)', 25, 'Which figure shows a concrete leaching chamber?', '["Figure 9","Figure 3","Figure 7","Figure 5"]', 2, 'Figure 7 shows a bottomless concrete leaching chamber, including interlocking design options. Section 4.4.3 (p.25).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q433', '4', '4.4.4 Infiltrative Chamber (Plastic)', 26, 'What design intent governs plastic infiltrative chambers?', '["They are installed per the technical intent of trench and mound fields","They are unregulated","They follow different rules entirely","They need no design"]', 0, 'Plastic chambers follow the technical intent of trench and mound fields: same separations, same even distribution, adapted to chambers. Section 4.4.4 (p.26).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q434', '4', '4.4.4 Infiltrative Chamber (Plastic)', 26, 'How must plastic chamber systems distribute effluent?', '["Downhill only","Randomly","All to one line","Evenly, with lines parallel to the contour"]', 3, 'Systems must distribute effluent evenly, with lines parallel to the contour (perpendicular to the natural slope). Even loading is the universal rule. Section 4.4.4 (p.26).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q435', '4', '4.4.4 Infiltrative Chamber (Plastic)', 26, 'Which figure diagrams an infiltrative chamber?', '["Figure 8","Figure 2","Figure 11","Figure 6"]', 0, 'Figure 8 diagrams an infiltrative chamber. Figures are in the handout package allowed in the exam. Section 4.4.4 (p.26).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q436', '4', '4.4.4 Infiltrative Chamber (Plastic)', 27, 'Whose installation guides must the Licensee follow for infiltrative chambers?', '["The plumbing code only","The Manufacturer''s Handling and Installation Guides","No guides exist","The installer''s preference"]', 1, 'The Licensee must install per the Manufacturer''s Handling and Installation Guides, contacting the manufacturer or distributors for details. Manufacturer instructions are mandatory, not optional. Section 4.4.4 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q437', '4', '4.4.4.1 Approved For Use in New Brunswick', 27, 'What is the unit length of the Quick4 High Capacity chamber?', '["6.25 ft","8 ft","5 ft","4 ft"]', 3, 'Quick4 High Capacity is 4 ft long, like the Standard version. Length matters because the 50 percent reduction applies per unit length. Section 4.4.4.1 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q438', '4', '4.4.4.1 Approved For Use in New Brunswick', 27, 'What is the unit length of the H-10 Standard chamber?', '["6.25 ft","5 ft","10 ft","4 ft"]', 0, 'H-10 Standard is 6.25 ft. The H-10 line comes in Standard and High Capacity, both 6.25 ft. Section 4.4.4.1 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q439', '4', '4.4.4.1 Approved For Use in New Brunswick', 27, 'What is the unit length of the Standard BioDiffuser?', '["5 ft","4 ft","6.25 ft","7 ft"]', 0, 'The Standard BioDiffuser is 6.25 ft. Section 4.4.4.1 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q440', '4', '4.4.4.1 Approved For Use in New Brunswick', 28, 'What is the unit length of the ARC 36 Standard chamber?', '["8 ft","4 ft","5 ft","6.25 ft"]', 2, 'ARC 36 Standard is 5 ft, as is the ARC 36 High Capacity. Section 4.4.4.1 (pp.27-28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q441', '4', '4.4.4.1 Approved For Use in New Brunswick', 27, 'Which manufacturer''s chambers are listed as approved?', '["Generic Chambers Inc","No manufacturer is named","Infiltrator Water Technologies, LLC","SepticPro Ltd"]', 0, 'All listed chambers are Infiltrator Water Technologies, LLC products. Only listed products are approved. Section 4.4.4.1 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q442', '4', '4.4.4.1 Approved For Use in New Brunswick', 27, 'Is the approved chamber list permanent?', '["It was repealed","It updates daily","It is subject to change","It is permanent"]', 2, 'The approved list is subject to change. Always check the current Guidelines before specifying a product. Section 4.4.4.1 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q443', '4', '4.4.4.1 Approved For Use in New Brunswick', 28, 'A design needs 100 m of pipe-and-stone field. How many metres of approved chambers are needed instead?', '["25 m","75 m","100 m","50 m"]', 3, 'A 100 m pipe-and-stone field needs 50 m of chambers after the 50 percent reduction. The reduction reflects chamber efficiency. Section 4.4.4.1 (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q444', '4', '4.4.4 Infiltrative Chamber (Plastic)', 26, 'What is recommended if the installer is uncertain about chamber sand?', '["Guess","Use clay","Skip the sand","Have a soil analysis completed"]', 3, 'If uncertain about sand, a soil analysis is recommended. Chamber performance depends on correct media. Section 4.4.4 (p.26).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q445', '4', '4.4.4 Infiltrative Chamber (Plastic)', 26, 'How are plastic chamber distribution lines oriented?', '["Down the slope","Vertically","In circles","Parallel to the contour (perpendicular to the natural slope)"]', 3, 'Lines run parallel to the contour, which is perpendicular to the natural slope. Contour-parallel lines distribute evenly across the slope. Section 4.4.4 (p.26).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q446', '4', '4.4.4.1 Approved For Use in New Brunswick', 27, 'What is the unit length of the H-10 High Capacity chamber?', '["7.5 ft","5 ft","4 ft","6.25 ft"]', 1, 'H-10 High Capacity is 6.25 ft, same as the H-10 Standard. Section 4.4.4.1 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q447', '4', '4.4.4.1 Approved For Use in New Brunswick', 28, 'What is the unit length of the ARC 36 High Capacity chamber?', '["4 ft","6.25 ft","5 ft","10 ft"]', 2, 'ARC 36 High Capacity is 5 ft, matching the ARC 36 Standard. Section 4.4.4.1 (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q448', '4', '4.4.4.1 Approved For Use in New Brunswick', 27, 'How many Quick4 models are listed?', '["One","Two: Standard and High Capacity","Four","Three"]', 1, 'The Quick4 line comes in Standard and High Capacity, both 4 ft. Two capacity options share one length. Section 4.4.4.1 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q449', '4', '4.4.4 Infiltrative Chamber (Plastic)', 27, 'The 1.0 m limiting-factor distance for plastic chambers is measured from where?', '["From the bottom of the trench (or unit)","From the pipe invert","From the tank","From the ground surface"]', 0, 'The 1.0 m is measured from the bottom of the trench or unit, not the pipe invert. Chambers sit in trenches, so the trench bottom is the reference. Section 4.4.4 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q450', '4', '4.4.4 Infiltrative Chamber (Plastic)', 27, 'Who should be contacted for chamber installation information?', '["The manufacturer or their distributors directly","No one","The municipality","The neighbour"]', 0, 'Chamber installers should contact the manufacturer or distributors directly for handling and installation information. Direct source beats hearsay. Section 4.4.4 (p.27).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q451', '4', '4.4.4.1 Approved For Use in New Brunswick', 28, 'How many chamber models are on the approved list?', '["Seven","Five","Three","Ten"]', 0, 'Seven Infiltrator products are listed: Quick4 Standard, Quick4 High Capacity, H-10 Standard, H-10 High Capacity, Standard BioDiffuser, ARC 36 Standard, ARC 36 High Capacity. Section 4.4.4.1 (pp.27-28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q452', '4', '4.4.5 Holding Tank', 28, 'When may a holding tank be installed?', '["For all new homes","For commercial kitchens","Only where there is no other reasonable or practical means of disposing of sewage","Whenever the owner prefers"]', 2, 'Holding tanks are a last resort, not a convenience option. The Guidelines restrict them to genuine no-outlet cases. Section 4.4.5 (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q453', '4', '4.4.5 Holding Tank', 28, 'Which site constraints justify a holding tank?', '["Large lots","High water tables only","Steep slopes, excessive rock, and limited lot size","Deep sand"]', 2, 'The Guidelines list steep slopes, excessive rock and limited lot size as site constraints justifying a holding tank. Section 4.4.5 (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q454', '4', '4.4.5 Holding Tank', 28, 'For which non-constraint sites are holding tanks considered?', '["Shopping malls","Schools","Year-round mansions","Seasonal sites with low waste, or where hauler servicing cannot be guaranteed (e.g. islands)"]', 3, 'Holding tanks are also considered for seasonal sites with low waste generation, or where servicing cannot be guaranteed by a septage hauler, such as islands. Section 4.4.5 (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q455', '4', '4.4.5 Holding Tank', 29, 'What retention time sizes a holding tank?', '["Three days","Seven days","Thirty days","One day"]', 1, 'Sizing uses residential sewage flows and a seven-day retention time, so a week of sewage fits between pump-outs. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q456', '4', '4.4.5 Holding Tank', 29, 'What is the minimum holding tank capacity?', '["3410 L (750 IG)","5000 L (1100 IG)","9000 L (2000 IG)","12000 L (2640 IG)"]', 2, 'Holding tanks must contain no less than 9000 L (2000 IG). Smaller tanks would overflow between hauls. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q457', '4', '4.4.5 Holding Tank', 29, 'At what level does the holding tank alarm activate?', '["95%","50%","100%","80%"]', 3, 'The alarm activates at 80 percent of capacity, giving the owner time to arrange a haul before it fills. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q458', '4', '4.4.5 Holding Tank', 29, 'How must the holding tank alarm alert occupants?', '["Audible and visible inside the building","No alarm is required","Outside only","A text message only"]', 0, 'The alarm must be both audible and visible inside the building, so occupants notice it in time. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q459', '4', '4.4.5 Holding Tank', 29, 'At what level does the pump interlock cut the water supply?', '["50%","90%","100%","80%"]', 3, 'A pump interlock stops water supply at 90 percent of capacity. Shutting off water prevents overflows after the alarm. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q460', '4', '4.4.5 Holding Tank', 29, 'How long may a temporary holding tank installation last?', '["Indefinitely","24 months","12 months","3 months"]', 2, 'Temporary installations may last up to 12 months. Beyond that a permanent solution is required. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q461', '4', '4.4.5 Holding Tank', 29, 'What is the maximum flow for a non-residential temporary holding tank?', '["90 litres per day (20 IG/day)","500 L/day","No limit","1000 L/day"]', 0, 'Non-residential temporary tanks must not exceed 90 litres per day (20 IG/day). Higher flows overwhelm a temporary tank. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q462', '4', '4.4.5 Holding Tank', 29, 'Who must hold a copy of the Septage Hauling Agreement?', '["The owner and the Department","The neighbour","The installer only","No one"]', 0, 'The owner and the Department must have a copy of the Septage Hauling Agreement. The agreement proves servicing is arranged. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q463', '4', '4.4.5 Holding Tank', 29, 'Which construction standard applies to holding tanks?', '["CAN/CSA B181","CSA B481","NSF 46","CSA B-66"]', 3, 'CSA B-66 is the referenced tank construction standard. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q464', '4', '4.4.5 Holding Tank', 29, 'What is encouraged to extend the period between pump-outs?', '["Larger tanks","Deeper burial","More occupants","Water-saving fixtures"]', 3, 'Water-saving fixtures reduce water usage and extend the period between septage pump-outs. Less water in means fewer hauls. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q465', '4', '4.4.5 Holding Tank', 29, 'How are holding tank owners billed for servicing?', '["Per bedroom","A flat annual fee","Nothing, it is free","On volume per septage load at current rates"]', 3, 'Holding tank owners are charged on volume per septage load at current rates, so conserving water saves money directly. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q466', '4', '4.4.5 Holding Tank', 28, 'Can a seepage pit serve as a holding tank?', '["Yes, if deep enough","Only with a pump","Yes, for seasonal use","No, seepage pits and cesspools do not treat effluent"]', 3, 'Seepage pits and cesspools do not treat effluent and cannot replace a holding tank. Only approved systems qualify. Section 4.4.5 (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q467', '4', '4.4.5 Holding Tank', 29, 'A seasonal cottage houses five people. What minimum tank size applies?', '["3500 L","7000 L","5000 L","9000 L (2000 IG)"]', 3, 'A five-person home at 500 L/day per residence needs 3500 L over seven days, but the 9000 L minimum governs, so the tank must be at least 9000 L. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q468', '4', '4.4.5 Holding Tank', 29, 'What are the two level-control stages in order?', '["80% then 90%","70% then 75%","90% then 100%","50% then 80%"]', 0, 'At 80 percent alarm the owner arranges a haul; at 90 percent the water shuts off. The two-stage system prevents overflows. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q469', '4', '4.4.5 Holding Tank', 28, 'What example is given of a site where hauler servicing cannot be guaranteed?', '["Farms","Islands","Subdivisions","Downtown lots"]', 1, 'Islands are the named example where hauler servicing cannot be guaranteed. No barge service means no pump-outs. Section 4.4.5 (p.28).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q470', '4', '4.4.5 Holding Tank', 29, 'What follows a 12-month temporary holding tank installation?', '["Nothing happens","It can renew forever","A permanent solution is required after 12 months","It becomes permanent automatically"]', 2, 'Temporary status ends at 12 months; a permanent approved system must follow. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q471', '4', '4.4.5 Holding Tank', 29, 'Who are the parties to the Septage Hauling Agreement?', '["The Department and the plumber","The owner and the septage hauler","The installer and the neighbour","No agreement is needed"]', 1, 'The Agreement is between the owner and the septage hauler. The Department holds a copy as proof. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q472', '4', '4.4.5 Holding Tank', 29, 'Why is the seven-day retention time significant?', '["It is arbitrary","It covers a full week of sewage between pump-outs","It matches the tank warranty","It matches the alarm level"]', 1, 'Seven-day retention covers a full week of flows between weekly hauls. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q473', '4', '4.4.5 Holding Tank', 29, 'A seasonal snack bar uses 90 L/day. What minimum tank size applies?', '["9000 L (2000 IG)","1000 L","No minimum","630 L only"]', 0, 'A 90 L/day non-residential use over seven days is 630 L, well under the 9000 L minimum, which still applies. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q474', '4', '4.4.5 Holding Tank', 29, 'How do the alarm and the pump interlock differ?', '["Only one is required","The alarm warns at 80%; the interlock stops water at 90%","The interlock comes first","They are the same"]', 1, 'The alarm warns at 80 percent; the interlock stops water at 90 percent. Both stages protect against overflow. Section 4.4.5 (p.29).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q475', '4', '4.4.6 Pit Privy', 30, 'When may a pit privy be built?', '["Schools","Only a temporary installation","Permanent homes","Shopping centres"]', 1, 'A privy is only a temporary installation, not a permanent sanitation solution. Permanent facilities need approved systems. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q476', '4', '4.4.6 Pit Privy', 30, 'Which sites are named as suitable for pit privies?', '["Work camps and seasonal dwellings","Restaurants","Year-round residences","Factories"]', 0, 'Work camps and seasonal dwellings are the named examples. Low, intermittent use suits a temporary privy. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q477', '4', '4.4.6 Pit Privy', 30, 'What condition must exist for a privy to be acceptable?', '["Where there is no other reasonable or practical method","Wherever the owner wants","In cities","Near wells"]', 0, 'Privies are only acceptable where there is no other reasonable or practical method of sewage disposal. They are a last resort. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q478', '4', '4.4.6 Pit Privy', 30, 'What is the maximum pit depth?', '["3.0 m (10 ft)","2.4 m (8 ft)","1.2 m (4 ft)","0.6 m (2 ft)"]', 2, 'Maximum pit depth is 1.2 m (4 ft). Deeper pits risk groundwater contact and collapse. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q479', '4', '4.4.6 Pit Privy', 30, 'From where is pit depth measured?', '["From the bedrock","From the seat","From the surface of the surrounding soil","From the water table"]', 2, 'Pit depth is measured from the surface of the surrounding soil. The measurement starts at grade, not at the seat. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q480', '4', '4.4.6 Pit Privy', 30, 'How far must a privy pit be from a drilled well?', '["15 m (50 ft)","30 m","5 m","60 m"]', 0, 'Pits must be at least 15 m (50 ft) from drilled wells. Privy waste must stay far from drinking water. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q481', '4', '4.4.6 Pit Privy', 30, 'How far must a privy pit be from a dug well?', '["30 m (100 ft)","15 m","10 m","60 m"]', 0, 'Pits must be at least 30 m (100 ft) from dug wells and surface water supplies. Dug wells and surface sources need extra protection. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q482', '4', '4.4.6 Pit Privy', 30, 'How far must a privy pit be from a surface water supply?', '["15 m","50 m","5 m","30 m (100 ft)"]', 3, 'Pits must be at least 30 m (100 ft) from surface water supplies, same as dug wells. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q483', '4', '4.4.6 Pit Privy', 30, 'Which separation rules apply to pit privies?', '["They are exempt","They use half distances","They follow Section 3.3","No distances apply"]', 2, 'Separation distances follow Section 3.3. Privies use the same protective distances as other systems. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q484', '4', '4.4.6 Pit Privy', 30, 'What childproofing does the seat opening require?', '["200 mm","50 mm","No bar needed","100 mm (4 in)"]', 3, 'The seat opening must be childproofed with a 100 mm (4 in) child bar across it. Children can fall into open pits. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q485', '4', '4.4.6 Pit Privy', 30, 'Is the child bar required if no children use the privy?', '["Only in summer","It is required regardless","Only if children are present","Never"]', 1, 'The child bar is mandatory regardless of whether children use the site. Safety rules do not depend on current occupants. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q486', '4', '4.4.6 Pit Privy', 30, 'What fly control does the privy superstructure need?', '["Open to the air","Screened against flies with a self-closing door","Air-conditioned","Heated"]', 1, 'The superstructure must be screened against flies and have a self-closing door. Flies spread disease from privies; screens and self-closing doors block them. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q487', '4', '4.4.6 Pit Privy', 30, 'What ventilation must the privy building have?', '["No ventilation","Sealed airtight","Recirculated indoor air","Outside ventilation"]', 3, 'The building needs outside ventilation. Ventilation controls odour and gases. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q488', '4', '4.4.6 Pit Privy', 30, 'What alternatives to pit privies are mentioned?', '["Soil absorption pits and bored wells","Mound systems","Holding tanks","Septic tanks"]', 0, 'Soil absorption pits and bored wells are alternative temporary options. They suit the same temporary, low-use situations. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q489', '4', '4.4.6 Pit Privy', 30, 'Before building a privy, what should be determined?', '["Determine whether the lot can sustain a conventional system","Call the hauler","Order the lumber","Dig immediately"]', 0, 'The installer should first determine whether the lot can sustain a conventional system. A privy is only justified when a real system is impossible. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q490', '4', '4.4.6 Pit Privy', 30, 'A pit is dug 1.5 m deep. Is it compliant?', '["Only in sand","Yes, deeper is better","Only in winter","No, 1.2 m is the maximum"]', 3, 'At 1.5 m the pit exceeds the 1.2 m maximum and must be shallower. Depth limits protect groundwater. Section 4.4.6 (p.30).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q491', '4', '4.4.7 Pump', 31, 'When is a pump used?', '["For every mound","Always","Never","When sewage cannot flow by gravity from the tank to the field"]', 3, 'A pump is used when sewage cannot flow by gravity from the septic tank to the field. Gravity is always preferred; pumps are the backup. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q492', '4', '4.4.7 Pump', 31, 'When does the 150 m maximum pumping distance apply?', '["The tank is at least 6 m above the highest point of the field","The tank is at the same elevation","Any situation","The field is uphill"]', 0, 'The 150 m maximum applies when the tank sits at least 6 m above the highest point of the field. Elevation head helps the pump. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q493', '4', '4.4.7 Pump', 31, 'What is the maximum pumping distance when the tank is less than 6 m above the field?', '["75 m","300 m","150 m","No limit"]', 0, 'When the tank is less than 6 m above the field, friction losses dominate and the maximum is 75 m. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q494', '4', '4.4.7 Pump', 31, 'Are the pumping distances fixed or variable?', '["They apply only to siphons","They are maximums; actual distance depends on pump size and type","They are minimums","They are exact requirements"]', 1, 'Both distances are maximums; actual pumping distance may be less depending on pump size and type. Pump capacity sets the real limit. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q495', '4', '4.4.7 Pump', 31, 'Are pressure distribution lines connected at the ends?', '["Connected at the ends","Connected in the middle","Looped together","Not connected at the ends"]', 3, 'Pressure distribution lines are not connected at the ends because each line is dosed under pressure independently. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q496', '4', '4.4.7 Pump', 31, 'Which table gives sizing criteria for pressure distribution?', '["Table 5","Table 3","Table 2","Appendix D"]', 0, 'The guidelines give sizing criteria for pressure distribution in Table 5. Table 5 is the design reference for pressure systems. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q497', '4', '4.4.7 Pump', 31, 'What dose volume per cycle do pumps deliver?', '["100%","10 to 25%","50 to 75%","5 to 10%"]', 2, 'Pumps dose the field with 50 to 75 percent of the daily flow per cycle. Small frequent doses rest the field between cycles. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q498', '4', '4.4.7 Pump', 31, 'What dosing frequency and capacity must a pump chamber provide?', '["Continuously","At least 1.2 times per day, handling 1.25 times the daily design flow","Once per week","Once per month"]', 1, 'The chamber pump must dose at least 1.2 times per day, and the system must handle 1.25 times the daily design flow. The multipliers provide surge capacity. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q499', '4', '4.4.7 Pump', 31, 'Design flow is 500 L/day. What capacity must the pump system handle?', '["500 L","1000 L","750 L","625 L"]', 3, 'At 500 L/day design flow, 1.25 times is 625 L/day capacity. The pump system must handle surges above the design flow. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q500', '4', '4.4.7 Pump', 31, 'Design flow is 500 L/day. What is one pump dose?', '["250 to 375 L","50 to 75 L","500 to 750 L","100 to 200 L"]', 0, 'At 500 L/day, a 50 to 75 percent dose is 250 to 375 L per cycle. Small doses rest the field between cycles. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q501', '4', '4.4.7 Pump', 31, 'Which figure shows a pump chamber?', '["Figure 11","Figure 4","Figure 9","Figure 7"]', 2, 'Figure 9 illustrates a pump chamber. Figures are in the handout package allowed in the exam. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q502', '4', '4.4.7 Pump', 31, 'Where are the pump, piping, and chambers housed?', '["Above ground only","Inside the septic tank","In the distribution box","Inside the pump chamber"]', 3, 'Pump, piping, and chambers sit inside the pump chamber. The pump chamber is a separate compartment or tank. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q503', '4', '4.4.7 Pump', 31, 'How do pressure line end connections differ from gravity lines?', '["Pressure lines are not connected at the ends; gravity line ends are connected","Pressure lines are larger","Gravity lines are capped","They are the same"]', 0, 'Pressure lines are independent, unlike gravity lines whose ends are connected. The design philosophies differ. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q504', '4', '4.4.7 Pump', 31, 'Can any pump achieve the 150 m maximum distance?', '["Yes, always","Distances are minimums","Not necessarily; it depends on pump size and type","Only with a siphon"]', 2, 'Actual distance depends on pump size and type, so an undersized pump cannot reach the maximum. Pump selection must match the run. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q505', '4', '4.4.7 Pump', 31, 'What is the main advantage of a pumped system?', '["They are cheaper","They need no maintenance","They serve sites gravity cannot reach","They are silent"]', 2, 'Pumps enable fields that gravity cannot reach, such as uphill or distant sites. Without a pump these sites could not be served. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q506', '4', '4.4.7 Pump', 31, 'How do the dosing frequency and dose volume rules relate?', '["One replaces the other","They conflict","They work together: frequent small doses cover the daily flow","Only one applies"]', 2, '1.2 doses per day at 50 to 75 percent per dose covers the daily flow with rest periods. The two rules work together. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q507', '4', '4.4.7 Pump', 31, 'What is Table 5 for?', '["Fees","Sizing criteria for pressure distribution","General guidance only","Tank sizes"]', 1, 'Table 5 holds the pressure distribution sizing criteria. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q508', '4', '4.4.7 Pump', 31, 'The tank outlet is above the field with good fall. Is a pump needed?', '["Use a siphon","No pump is needed if gravity works","Install a pump anyway","Use two pumps"]', 1, 'A pump is used only when gravity flow is impossible. If gravity works, no pump is needed. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q509', '4', '4.4.7 Pump', 31, 'The field is 100 m away and the tank is 3 m above it. Is this acceptable?', '["Yes if downhill","Yes","Only with a bigger tank","No, 75 m is the maximum in that case"]', 3, 'At 75 m with less than 6 m of elevation, the 75 m maximum applies and a 100 m run exceeds it. Section 4.4.7 (p.31).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q510', '4', '4.4.8 Grease Trap', 32, 'What is the purpose of a grease trap?', '["To heat the effluent","To add grease","To measure flow","To keep fats, oils and grease out of the system"]', 3, 'Grease traps keep fats, oils and grease out of the septic system. FOG clogs pipes and kills field biology. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q511', '4', '4.4.8 Grease Trap', 32, 'Which facilities need grease traps?', '["Restaurants and food preparation establishments","Car washes","Gas stations","Single-family homes"]', 0, 'Restaurants and food preparation establishments are the named examples. Commercial kitchens produce heavy FOG loads. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q512', '4', '4.4.8 Grease Trap', 32, 'Which standard applies to grease traps?', '["CSA B481-07","CAN/CSA B181","NSF 46","CSA B66"]', 0, 'Grease traps must meet CSA B481-07. The standard covers design and performance. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q513', '4', '4.4.8 Grease Trap', 32, 'Why must chemicals not be added to grease traps?', '["They push grease downstream instead of trapping it","They are too expensive","They improve trapping","They corrode concrete"]', 0, 'Chemicals must not be added because they push grease downstream instead of trapping it. Trapped grease must stay in the trap. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q514', '4', '4.4.8 Grease Trap', 32, 'How often must grease be removed from the trap?', '["Never","Only on sale","Once a decade","Regularly"]', 3, 'Grease must be removed regularly so the trap keeps working. A full trap passes grease straight through. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q515', '4', '4.4.8 Grease Trap', 32, 'What does FOG stand for?', '["Flow output gauge","Fast organic growth","Field operating guide","Fats, oils and grease"]', 3, 'FOG stands for fats, oils and grease. Appendix E sets the 35 mg/L FOG influent limit. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q516', '4', '4.4.8 Grease Trap', 32, 'Why is FOG harmful to septic systems?', '["It is harmless","It coats pipes and soil pores, blocking treatment","It helps bacteria","It adds nutrients"]', 1, 'FOG coats pipes and soil pores, blocking treatment. That is why traps and the 35 mg/L limit exist. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q517', '4', '4.4.8 Grease Trap', 32, 'Which figure shows a grease trap?', '["Figure 12","Figure 10","Figure 9","Figure 8"]', 1, 'Figure 10 shows a typical grease trap. Figures are in the handout package allowed in the exam. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q518', '4', '4.4.8 Grease Trap', 32, 'A restaurant owner wants to add a grease-eating chemical to the trap. Allowed?', '["No, chemicals push grease downstream","Only on weekends","Yes, they help","Only natural ones"]', 0, 'A chemical additive that emulsifies grease sends it downstream to clog the field. Additives defeat the trap. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q519', '4', '4.4.8 Grease Trap', 32, 'Where is the grease trap installed?', '["Inside the well","On the roof","After the field","On the kitchen line before the septic tank"]', 3, 'The trap sits on the kitchen line before the septic tank, so FOG never reaches the tank or field. Section 4.4.8 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q520', '4', '4.4.9 Oil/Water Separator', 32, 'What is the purpose of an oil/water separator?', '["To store oil","To keep petroleum products out of the septic system","To add oil","To heat water"]', 1, 'Oil/water separators keep petroleum out of septic systems. Oil kills the biology that treats sewage. Section 4.4.9 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q521', '4', '4.4.9 Oil/Water Separator', 32, 'Which facilities need oil/water separators?', '["Homes","Restaurants","Schools","Garages and vehicle service facilities"]', 3, 'Garages and vehicle service facilities are the named examples. These sites handle oil and fuel routinely. Section 4.4.9 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q522', '4', '4.4.9 Oil/Water Separator', 32, 'Can domestic sewage discharge through an oil/water separator?', '["Yes, always","No","Only in winter","Only on weekends"]', 1, 'Domestic sewage must not discharge through an oil/water separator. Sewage would overwhelm it and contaminate the oil stream. Section 4.4.9 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q523', '4', '4.4.9 Oil/Water Separator', 32, 'Who approves oil/water separator installations?', '["No one","The municipality","DELG (Department of Environment and Local Government)","The installer"]', 2, 'DELG is the Department of Environment and Local Government, the authority for separator approvals. Section 4.4.9 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q524', '4', '4.4.9 Oil/Water Separator', 32, 'How are shop wastewater and domestic sewage handled at a garage?', '["Keep them separate: sewage to septic, shop water to separator","Send both to the ditch","Combine them","Send both to the separator"]', 0, 'Separators handle shop wastewater; domestic sewage goes to the septic system separately. The streams must not mix. Section 4.4.9 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q525', '4', '4.4.9 Oil/Water Separator', 32, 'Why must petroleum stay out of septic systems?', '["It coats biology and soil pores, destroying treatment","It adds nutrients","It evaporates harmlessly","It helps treatment"]', 0, 'Oil coats the treatment biology and soil pores, destroying the system''s ability to treat effluent. Section 4.4.9 (p.32).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q526', '4', '4.5 Repairs', 33, 'What counts as a repair?', '["Adding bedrooms","Paving the lot","Fixing broken pipes and baffles, replacing filters","Building a new field"]', 2, 'Repairs include fixing broken pipes and baffles, replacing filters, and restoring failed components. Like-for-like repair keeps the approved system working. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q527', '4', '4.5 Repairs', 33, 'What is the goal of a repair?', '["Making it bigger","Changing the technology","Any change the owner wants","Restoring the system to its approved design"]', 3, 'Repairs restore the system to its approved design. Upgrades or expansions are new approvals, not repairs. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q528', '4', '4.5 Repairs', 33, 'When must the Department be notified about a repair?', '["Only for big jobs","Never","Before starting repair work","After finishing"]', 2, 'The Licensee must notify the Department before starting repair work. The Department tracks all work on regulated systems. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q529', '4', '4.5 Repairs', 33, 'The disposal field has failed. Is this a repair?', '["Ignore it","Patch it with more stone","Add a pump","A new approval and replacement field"]', 3, 'A failed field cannot be patched; it needs a new approval and replacement. Repairs cover components, not failed disposal fields. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q530', '4', '4.5 Repairs', 33, 'Which Public Health Act section governs repairs?', '["Section 12","No section","Section 30","Section 24"]', 3, 'Section 24 of the Public Health Act is the authority cited for repairs. The Act backs the repair rules. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q531', '4', '4.5 Repairs', 33, 'Who may perform repairs?', '["A Licensed installer","A plumber only","Anyone","The owner only"]', 0, 'Only a Licensed installer may do repair work on regulated systems. Unlicensed work is an offence. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q532', '4', '4.5 Repairs', 33, 'Which of these is a repair?', '["Replacing a clogged effluent filter","Adding a bedroom","Digging a new field","Moving the tank"]', 0, 'Replacing a clogged effluent filter restores flow and is a classic repair. Filters are maintenance items. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q533', '4', '4.5 Repairs', 33, 'An owner wants a bigger field during a repair visit. What is needed?', '["No paperwork needed","Notify as a repair","Just do it","Apply for a new approval"]', 3, 'Expanding the field changes the approved design, so it needs a new approval, not a repair notification. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q534', '4', '4.5 Repairs', 33, 'Why does the Department require repair notification?', '["It is optional","To verify work matches the approved system","To collect fees","To delay the job"]', 1, 'Notification lets the Department verify the work matches the approved system. Unreported work cannot be verified. Section 4.5 (p.33).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q535', '4', '4.6 Non-Conventional Design', 34, 'What is a non-conventional design?', '["Conventional systems","Holding tanks","Systems not described in the Guidelines that still treat sewage safely","Illegal systems"]', 2, 'Non-conventional designs are systems not described in the Guidelines that still treat sewage safely. Innovation is allowed with engineering oversight. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q536', '4', '4.6 Non-Conventional Design', 34, 'Who must design a non-conventional system?', '["The owner","A Professional Engineer","Any installer","No one"]', 1, 'A Professional Engineer must design and stamp non-conventional systems. Engineering accountability replaces prescriptive rules. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q537', '4', '4.6 Non-Conventional Design', 34, 'Which form applies to non-conventional system approval?', '["Form C","No form","Form B","Form A"]', 3, 'Form A is the Application for Approval for non-conventional systems. Using the right form starts the process correctly. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q538', '4', '4.6 Non-Conventional Design', 34, 'What does the Professional Engineer''s stamp signify?', '["It is decorative","It certifies the design meets treatment objectives","It replaces the application","It is optional"]', 1, 'The engineer''s stamp certifies the design meets treatment objectives. The stamp is professional accountability. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q539', '4', '4.6 Non-Conventional Design', 34, 'How are non-conventional applications handled?', '["They are auto-approved","The installer approves","The Department reviews them","No review is needed"]', 2, 'The Department reviews non-conventional applications for safety and performance. Review protects public health. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q540', '4', '4.6 Non-Conventional Design', 34, 'Which is a named example of non-conventional technology?', '["Aerobic treatment units","Pipe and stone","Seepage pits","Pit privies"]', 0, 'Aerobic treatment units are named examples of non-conventional technology. They treat beyond septic tank levels. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q541', '4', '4.6 Non-Conventional Design', 34, 'Which dispersal method is non-conventional?', '["Mound trenches","Chambers","Gravity trenches","Drip irrigation"]', 3, 'Drip irrigation is a named non-conventional dispersal method. It doses effluent slowly through tubing. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q542', '4', '4.6 Non-Conventional Design', 34, 'What must a non-conventional design demonstrate?', '["It is fast to build","It looks nice","It is cheap","It will treat sewage to protect health and the environment"]', 3, 'The design must show the system will treat sewage to protect health and the environment. Performance proof replaces prescriptive dimensions. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q543', '4', '4.6 Non-Conventional Design', 34, 'How do conventional and non-conventional approvals differ?', '["Conventional needs an engineer","Conventional follows prescriptive rules; non-conventional needs engineered proof","They are identical","Non-conventional is easier"]', 1, 'Conventional systems follow prescriptive rules; non-conventional systems need engineered performance proof. The paths differ but the goal is the same. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q544', '4', '4.6 Non-Conventional Design', 34, 'Is monitoring required for non-conventional systems?', '["Monitoring is prohibited","Monitoring may be required","Never","Only for conventional"]', 1, 'Monitoring may be required to verify a non-conventional system performs as designed. Novel systems earn trust through data. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q545', '4', '4.6 Non-Conventional Design', 34, 'A new chamber brand is not on the approved list. How is it handled?', '["Treat it as non-conventional with engineering and approval","Install it as conventional","Use it without paperwork","It is automatically approved"]', 0, 'An unlisted chamber brand is non-conventional and needs engineering and Department approval. The approved list is the conventional path. Section 4.6 (p.34).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q546', '5', '5.1-5.2 Licensing', 36, 'Who may install an on-site sewage disposal system?', '["Anyone with a shovel","Only the owner","Only engineers","Only Licensed installers"]', 3, 'Only Licensed installers may install on-site sewage systems. Licensing protects public health through qualified installers. Section 5.1 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q547', '5', '5.1-5.2 Licensing', 36, 'What is the penalty for installing without a licence?', '["It is an offence under the Public Health Act","It is a minor warning","Nothing happens","It is allowed"]', 0, 'Installing without a licence is an offence under the Public Health Act. The Act gives licensing its teeth. Section 5.1 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q548', '5', '5.1-5.2 Licensing', 36, 'What is the installer licence fee?', '["$350","$500","$400","$150"]', 2, 'The licence fee is $400. Fees are set in the Guidelines and collected with the application. Section 5.2 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q549', '5', '5.1-5.2 Licensing', 36, 'What is the licence renewal fee?', '["$200","$350","$400","$150"]', 1, 'Renewal costs $350, less than the initial $400. Renewal rewards continuing installers. Section 5.2 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q550', '5', '5.1-5.2 Licensing', 36, 'When do installer licences expire?', '["June 30","March 31","The anniversary date","December 31"]', 1, 'Licences expire March 31 each year. Every installer renews on the same cycle. Section 5.2 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q551', '5', '5.1-5.2 Licensing', 36, 'Who holds the installer licence?', '["The individual","No one","The company","The Department"]', 2, 'The licence is held by the company, not the individual. If the licensed person leaves, the company must replace them. Section 5.2 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q552', '5', '5.1-5.2 Licensing', 36, 'How long does a company have to replace a departing licensed person?', '["30 days","90 days","7 days","One year"]', 0, 'The company has 30 days to replace a departing licensed person. Work cannot continue unlicensed beyond that. Section 5.2 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q553', '5', '5.2.1 Issuance', 37, 'What must an applicant provide for licence issuance?', '["A high school diploma","Nothing","A driver''s licence","The course certificate"]', 3, 'The course certificate is required before a licence issues. Training comes before licensing. Section 5.2.1 (p.37).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q554', '5', '5.2.1 Issuance', 37, 'What does a licence application require?', '["A reference letter","Just the fee","Just a phone call","Fee, course certificate, and company details"]', 3, 'The application needs the fee, the course certificate, and company details. All three together complete the application. Section 5.2.1 (p.37).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q555', '5', '5.2.1 Issuance', 37, 'Who issues the installer licence?', '["It is automatic","The municipality issues it","The installer prints it","The Department issues it"]', 3, 'The Department issues the licence after verifying the requirements. Issuance is the Department''s act, not automatic. Section 5.2.1 (p.37).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q556', '5', '5.1-5.2 Licensing', 36, 'A company installs systems with no licensed person for 60 days. What is the risk?', '["A small fine only","A warning letter","Nothing","Prosecution under the Public Health Act"]', 3, 'Working unlicensed risks prosecution under the Public Health Act. The offence applies to the worker and the company. Section 5.1 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q557', '5', '5.1-5.2 Licensing', 36, 'A new installer asks what to pay with the first application. How much?', '["$400","$500","$350","$150"]', 0, 'The $400 fee applies to the initial licence; renewal is $350. Mixing them up overpays or underpays. Section 5.2 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q558', '5', '5.1-5.2 Licensing', 36, 'A company hires a new installer. Are they covered by the company licence?', '["They can work forever","They are covered","No licence is needed","They need their own licensing; the licence is company-held"]', 3, 'Because the licence belongs to the company, the new hire needs their own licensing path. The company licence does not transfer to individuals. Section 5.2 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q559', '5', '5.1-5.2 Licensing', 36, 'A licence expires March 31. When must renewal happen?', '["Expiry does not matter","They get a grace year","They must renew before April 1","They have until June"]', 2, 'Expiry on March 31 means renewal before April 1. Late renewal leaves the installer unlicensed. Section 5.2 (p.36).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q560', '5', '5.3 Course and Exam', 38, 'How long is the installer exam?', '["3 hours","4 hours","1 hour","2 hours"]', 0, 'The exam is 3 hours long. Time management matters across the whole Guidelines. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q561', '5', '5.3 Course and Exam', 38, 'What is the exam pass mark?', '["60%","85%","50%","70%"]', 1, 'The pass mark is 85 percent. The high bar reflects the public health stakes. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q562', '5', '5.3 Course and Exam', 38, 'Is the exam open-book or closed-book?', '["Closed-book","Take-home","Oral only","Open-book"]', 3, 'The exam is open-book, with the Guidelines and handouts allowed. Knowing where to find rules beats memorizing them. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q563', '5', '5.3 Course and Exam', 38, 'Can a failed exam be rewritten?', '["Never","Only with a new course","Yes, after a waiting period","Only once ever"]', 2, 'A failed exam may be rewritten after a waiting period. The rewrite rule gives candidates another chance. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q564', '5', '5.3 Course and Exam', 38, 'What does the installer course cover?', '["Only regulations","Only theory","The full Guidelines plus hands-on practice","Only math"]', 2, 'The course covers the full Guidelines plus hands-on installation practice. Both theory and practice are examined. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q565', '5', '5.3 Course and Exam', 38, 'What may candidates bring to the exam?', '["Nothing","The Guidelines, handouts, and a calculator","Only a pen","A laptop"]', 1, 'Bring the Guidelines, the handout package with figures, and a calculator. The right materials make open-book work. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q566', '5', '5.3 Course and Exam', 38, 'A candidate scores 84%. Do they pass?', '["No, 85% is the pass mark","Only with extra credit","It rounds up","Yes"]', 0, 'At 85 percent, an 84 percent score fails. Every question counts at the high pass mark. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q567', '5', '5.3 Course and Exam', 38, 'What exam time strategy fits the 3-hour limit?', '["Skip the math","Answer randomly","Pace evenly across all sections","Rush the start"]', 2, 'Three hours for the whole exam means pacing across all sections. Slow starts risk unfinished sections. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q568', '5', '5.3 Course and Exam', 38, 'What skill matters most in an open-book exam?', '["Finding rules quickly in the Guidelines","Copying neighbours","Guessing","Memorizing everything"]', 0, 'Open-book means the skill is finding rules fast in the Guidelines. Tabbing key tables pays off. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q569', '5', '5.3 Course and Exam', 38, 'When can a failed candidate rewrite?', '["Never","Immediately","After the waiting period","The next day"]', 2, 'The waiting period applies between attempts. Immediate rewrites are not allowed. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q570', '5', '5.3 Course and Exam', 38, 'What does passing the exam earn?', '["A discount","The course certificate needed for licensing","Nothing","A trophy"]', 1, 'The course certificate is the licence prerequisite. Passing the exam earns the certificate. Section 5.3 (p.38).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q571', '5', '5.4 Application Process', 39, 'What is the system approval application fee?', '["$350","$50","$150","$400"]', 2, 'The application fee is $150. It accompanies the system approval application. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q572', '5', '5.4 Application Process', 39, 'How quickly are applications assessed?', '["7 days","30 days","90 days","1 day"]', 0, 'The Department assesses applications within 7 days. Applicants get a prompt decision. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q573', '5', '5.4 Application Process', 39, 'How much notice is required before starting construction?', '["30 days","No notice","3 days","7 days"]', 2, 'Three days notice is required before construction starts. Notice lets inspectors schedule site visits. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q574', '5', '5.4 Application Process', 39, 'What is the re-inspection fee?', '["$400","Free","$150","$50"]', 2, 'Re-inspection costs $150. Failed inspections cost the installer real money. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q575', '5', '5.4 Application Process', 39, 'How long do owners have to submit required documents?', '["30 days","3 days","60 days","10 days"]', 3, 'Owners must submit required documents within 10 days. The file cannot close without them. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q576', '5', '5.4 Application Process', 39, 'How long is a system approval valid?', '["12 months","Never","6 months","24 months"]', 0, 'Approvals expire 12 months after issuance. Stale approvals do not reflect current site conditions. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q577', '5', '5.4 Application Process', 39, 'How long must installation records be kept?', '["7 years","3 years","1 year","10 years"]', 0, 'Records must be kept 7 years. Long retention covers the system''s early life and any disputes. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q578', '5', '5.4 Application Process', 39, 'What does a system approval application include?', '["Just the fee","Nothing","Site plan, soil info, system design, and fee","A phone call"]', 2, 'The application needs the site plan, soil information, system design, and the fee. Complete applications are assessed in 7 days. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q579', '5', '5.4 Application Process', 39, 'Can construction start before approval is issued?', '["No, approval must come first","Only on weekends","Only for repairs","Yes"]', 0, 'Construction without approval is an offence. Approval must come first. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q580', '5', '5.4 Application Process', 39, 'Construction starts Monday. When is notice due?', '["No notice needed","The prior Friday","Monday morning","A month before"]', 1, 'Starting Monday needs notice by the prior Friday (3 days). Counting backwards sets the notice date. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q581', '5', '5.4 Application Process', 39, 'An approval was issued 14 months ago and work never started. Valid?', '["It renews automatically","It is still valid","It expired at 12 months; reapply","Extensions are automatic"]', 2, 'An approval issued last January expired this January at 12 months. A new application is needed. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q582', '5', '5.4 Application Process', 39, 'An inspection fails twice. What fees apply?', '["Nothing","Licence loss","$400","$150 per re-inspection"]', 3, 'Each failed inspection triggers the $150 re-inspection fee. Passing the first time saves money. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q583', '5', '5.4 Application Process', 39, 'An installer wants to discard 6-year-old records. Allowed?', '["It does not matter","Keep one year","Discard them","Keep them; 7-year retention"]', 3, 'The 7-year retention means records from six years ago must still exist. Only older than seven may be discarded. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q584', '5', '5.4 Application Process', 39, 'Application fee plus one re-inspection totals what?', '["$150","$500","$400","$300"]', 3, 'The $150 application fee and the $150 re-inspection fee are separate charges. Budget for both. Section 5.4 (p.39).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q585', '5', '5.5 Revoking an Approval', 41, 'When may an approval be revoked?', '["Only by court order","Never","At any time for any reason","For non-compliance with approval conditions"]', 3, 'Approvals may be revoked for non-compliance with the approval conditions. Conditions are binding, not advisory. Section 5.5 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q586', '5', '5.5 Revoking an Approval', 41, 'What process precedes revocation?', '["Immediate revocation","A phone call only","Notice and a chance to respond","No notice needed"]', 2, 'The holder gets notice and a chance to respond before revocation. Due process applies. Section 5.5 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q587', '5', '5.5 Revoking an Approval', 41, 'The installer builds differently from the approved design. What is the risk?', '["It is fine","It breaches the conditions and risks revocation","Verbal approval suffices","It only needs a note"]', 1, 'Building differently from the approved design breaches the approval conditions. As-builts must match the approval. Section 5.5 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q588', '5', '5.5.1 Certificate of Compliance', 41, 'What is the Certificate of Compliance?', '["A warranty","A bill","Certification that the installation matches the approved design","A tax receipt"]', 2, 'The Certificate of Compliance certifies the installation matches the approved design. It closes the file. Section 5.5.1 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q589', '5', '5.5.1 Certificate of Compliance', 41, 'Who signs the Certificate of Compliance?', '["The owner","The neighbour","No one","The Licensee"]', 3, 'The Licensee signs the certificate, taking professional responsibility for the match. Section 5.5.1 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q590', '5', '5.5.1 Certificate of Compliance', 41, 'When is the Certificate of Compliance issued?', '["Anytime","After final inspection","Before construction","Never"]', 1, 'The certificate is issued after final inspection passes. Inspection verifies the match first. Section 5.5.1 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q591', '5', '5.5.1 Certificate of Compliance', 41, 'What if no Certificate of Compliance is ever issued?', '["The system lacks formal approval","A fine only","Nothing, it is optional","It is automatically approved"]', 0, 'Without the certificate the file stays open and the system is not formally approved. The certificate is the final step. Section 5.5.1 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q592', '5', '5.5 Revoking an Approval', 41, 'Which of these can trigger revocation?', '["Using a different pen","Non-compliance with approval conditions","Being late once","Any typo"]', 1, 'Revocation follows non-compliance with conditions. Minor paperwork issues are corrected, not punished by revocation. Section 5.5 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q593', '5', '5.5.1 Certificate of Compliance', 41, 'What is the purpose of the Certificate of Compliance?', '["Nothing","Documenting that the build matches the approval","Advertising","Marketing"]', 1, 'The certificate documents that what was built matches what was approved. It is the as-built record. Section 5.5.1 (p.41).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q594', '6', 'Appendix A Soil Texture', 44, 'What does Appendix A contain?', '["Sludge rates","Sizing tables","Sewage flows","The soil texture flow diagram"]', 3, 'Appendix A holds the soil texture flow diagram used with the texture-by-feel method. The diagram turns feel into classification. Appendix A (p.44).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q595', '6', 'Appendix A Soil Texture', 44, 'How is the Appendix A flow chart used?', '["Use a lab only","Follow the flow chart steps","Guess","Ask the owner"]', 1, 'The flow chart in Appendix A walks through the texture-by-feel steps to a soil texture name. Each answer narrows the texture. Appendix A (p.44).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q596', '6', 'Appendix B Sizing Tables', 45, 'What does Appendix B contain?', '["Exam questions","Fees","System sizing tables","Office addresses"]', 2, 'Appendix B holds the system sizing tables by soil category. Sizing starts in Appendix B. Appendix B (p.45).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q597', '6', 'Appendix B1 Sizing Table', 46, 'Which soil category does Appendix B1 address?', '["Category A","Category B","Category C","Category D"]', 3, 'Appendix B1 covers Category D soils, which need the largest systems. Category D drains slowest. Appendix B1 (p.46).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q598', '6', 'Appendix B Sizing Tables', 45, 'What do the sizing tables provide?', '["The exam date","The installer name","The tank colour","Required field length for flow and soil category"]', 3, 'Sizing tables give the required field length for the flow and soil category. Look up flow, then soil. Appendix B (p.45).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q599', '6', 'Appendix B Sizing Tables', 45, 'How do Category A and D sizing requirements compare?', '["They are the same","Tables do not differ","Category A needs longer fields","Category D needs longer fields"]', 3, 'Longer fields are needed for slower soils, so Category D needs more length than Category A. Permeability drives the difference. Appendix B (p.45).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q600', '6', 'Appendix C Test Holes', 47, 'What does Appendix C cover?', '["Fees","Exam rules","Tank sizes","Test hole requirements"]', 3, 'Appendix C sets test hole requirements: depth, number, and observation. Test holes reveal the limiting factors. Appendix C (p.47).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q601', '6', 'Appendix C Test Holes', 47, 'How deep must test holes go?', '["To bedrock always","1 m always","Just the topsoil","Below the proposed system depth"]', 3, 'Test holes must reach below the proposed system depth to expose limiting factors. Shallow holes miss the critical zone. Appendix C (p.47).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q602', '6', 'Appendix C Test Holes', 47, 'How many test holes are needed?', '["One","Multiple across the field area","Only at the tank","None"]', 1, 'Multiple holes across the field area capture soil variation. One hole cannot represent a whole field. Appendix C (p.47).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q603', '6', 'Appendix D Sewage Flows', 48, 'What does Appendix D contain?', '["Exam answers","Tank prices","Estimated daily sewage flows","Soil types"]', 2, 'Appendix D lists estimated daily sewage flows by fixture and occupancy. Flow estimation starts in Appendix D. Appendix D (p.48).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q604', '6', 'Appendix D Sewage Flows', 48, 'What drives residential flow estimates?', '["Driveway length","Roof area","Lot size","Bedrooms and occupancy"]', 3, 'Residential flow uses bedrooms and occupancy. More bedrooms means more flow. Appendix D (p.48).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q605', '6', 'Appendix D Sewage Flows', 48, 'What drives non-residential flow estimates?', '["Owner name","Lot size","Bedrooms","Fixture counts and use type"]', 3, 'Non-residential flows use fixture counts and use type. A restaurant and an office with the same fixtures differ. Appendix D (p.48).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q606', '6', 'Appendix E Influent Quality', 49, 'What does Appendix E contain?', '["Fees","Influent quality limits (BOD5, TSS, FOG)","Soil textures","Flow rates"]', 1, 'Appendix E sets influent quality limits: BOD5 300 mg/L, TSS 350 mg/L, FOG 35 mg/L. Strong waste needs pretreatment. Appendix E (p.49).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q607', '6', 'Appendix E Influent Quality', 49, 'What does BOD5 measure?', '["pH","Oxygen demand over five days","Flow rate","Bacteria count"]', 1, 'BOD5 measures the oxygen demand of the waste over five days. High BOD5 means strong sewage. Appendix E (p.49).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q608', '6', 'Appendix E Influent Quality', 49, 'What does TSS stand for?', '["Tank sludge depth","Soil salinity","Total suspended solids","Total dissolved gas"]', 2, 'TSS is total suspended solids, the particles in the waste. High TSS clogs fields. Appendix E (p.49).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q609', '6', 'Appendix F Sludge and Scum', 50, 'What does Appendix F contain?', '["Soil textures","Exam questions","Sludge and scum accumulation rates","Flow rates"]', 2, 'Appendix F gives sludge and scum accumulation rates for sizing non-residential tanks. Pump-out intervals come from these rates. Appendix F (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q610', '6', 'Appendix F Sludge and Scum', 50, 'Why do sludge and scum rates matter?', '["For no reason","To pick the colour","To size tanks and set pump-out intervals","To set fees"]', 2, 'Accumulation rates size the tank so pump-outs happen before sludge reaches the outlet. A full tank passes solids to the field. Appendix F (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q611', '6', 'Appendix F Sludge and Scum', 50, 'What happens if sludge is never pumped?', '["Solids flow to the field and clog it","Nothing","The tank gets cleaner","Flow improves"]', 0, 'If sludge reaches the outlet baffle, solids flow to the field and clog it. Pump-outs must come first. Appendix F (p.50).');
INSERT INTO questions (id, chapter, section, page, question, options, answer, explanation) VALUES ('q612', '4', '4.4.1 Pipe and Stone In-ground Trench', 19, 'Why are in-ground trenches described as being excavated into original ground rather than fill?', '["Undisturbed native soil has the tested permeability the design relies on","It is cheaper","It is faster","Fill is stronger"]', 0, 'The disposal field must be built in the same undisturbed soil that was tested and classified during lot evaluation. Fill has unknown, inconsistent permeability and cannot be trusted to treat effluent. Section 4.4.1 (p.18).');